// epochFence is a controllable authority lease.
type epochFence struct {
	epoch  atomic.Uint64
	leader atomic.Bool
	// lost makes Guard fail while Current still reports the lease, as
	// when the lease expires during a tick.
	lost atomic.Bool
}

func newFence(epoch uint64) *epochFence {
	fence := &epochFence{}
	fence.epoch.Store(epoch)
	fence.leader.Store(true)
	return fence
}

func (fence *epochFence) Current() authority.Snapshot {
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true, Leader: fence.leader.Load(), Epoch: fence.epoch.Load(), Revision: 1,
		ExpiresAt: time.Now().Add(time.Hour)}
}

func (fence *epochFence) Guard(_ context.Context, epoch uint64) error {
	if !fence.leader.Load() || fence.lost.Load() || epoch == 0 || epoch != fence.epoch.Load() {
		return authority.ErrFenced
	}
	return nil
}

