// Accepted reports whether the unit runs, or is moving to, the release.
func (outcome StepOutcome) Accepted() bool {
	return outcome == OutcomeActivated || outcome == OutcomePending || outcome == OutcomeCurrent
}

trust_sign_verify.text:
func EncodePayload(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust payload: %w", err)
	}
	if err := validatePayload(encoded); err != nil {
		return nil, err
	}
	return encoded, nil
}

// Sign signs a strict, bounded JSON object for the exact supplied scope.
func Sign(payload []byte, scope Scope, issuedAt, expiresAt time.Time, privateKey ed25519.PrivateKey) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: invalid Ed25519 private key", ErrInvalid)
	}
	if err := scope.validate(); err != nil {
		return Envelope{}, err
	}
	compact, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validTime(issuedAt) || !validTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: invalid trust validity interval", ErrInvalid)
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: SchemaVersion,
		KeyID:         keyID,
		Scope:         scope,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		Payload:       compact,
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

// EncodeEnvelope emits the single deterministic JSON wire representation.
func EncodeEnvelope(envelope Envelope) ([]byte, error) {
	if err := envelope.validateShape(); err != nil {
		return nil, err
	}
	encoded, err := json.Marshal(envelope, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust envelope: %w", err)
	}
	if len(encoded) > MaxEnvelopeBytes {
		return nil, fmt.Errorf("%w: encoded envelope exceeds size limit", ErrInvalid)
	}
	return encoded, nil
}

// DecodeEnvelope strictly decodes one canonical wire envelope. Unknown or
// duplicate fields, alternate outer JSON encodings, and oversized payloads fail.
func DecodeEnvelope(encoded []byte) (Envelope, error) {
	if len(encoded) == 0 || len(encoded) > MaxEnvelopeBytes {
		return Envelope{}, fmt.Errorf("%w: envelope is empty or too large", ErrInvalid)
	}
	var envelope Envelope
	if err := protocol.DecodeStrict(encoded, &envelope, MaxEnvelopeBytes); err != nil {
		return Envelope{}, fmt.Errorf("decode trust envelope: %w", err)
	}
	canonical, err := EncodeEnvelope(envelope)
	if err != nil {
		return Envelope{}, err
	}
	if string(canonical) != string(encoded) {
		return Envelope{}, fmt.Errorf("%w: envelope JSON is not canonical", ErrInvalid)
	}
	return envelope, nil
}

// VerifyCurrent verifies the exact scope, signature, lifetime, and current
// validity. Use this API before any current mutation or secret retrieval.
func VerifyCurrent(envelope Envelope, expected Scope, keys Keyring, now time.Time, policy Policy) ([]byte, error) {
	if !validTime(now) || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
		return nil, ErrNotYetValid
	}
	if !now.Before(envelope.ExpiresAt) {
		return nil, ErrExpired
	}
	return bytesClone(envelope.Payload), nil
}

trust_signature.text:
func verifySignature(envelope Envelope, expected Scope, keys Keyring, maximumLifetime time.Duration) error {
	if err := envelope.validateShape(); err != nil {
		return err
	}
	if err := expected.validate(); err != nil {
		return err
	}
	if envelope.Scope != expected {
		return ErrScopeMismatch
	}
	if !envelope.ExpiresAt.After(envelope.IssuedAt) || envelope.ExpiresAt.Sub(envelope.IssuedAt) > maximumLifetime {
		return fmt.Errorf("%w: invalid or excessive trust validity interval", ErrInvalid)
	}
	publicKey, exists := keys[envelope.KeyID]
	if !exists {
		return ErrUntrustedKey
	}
	keyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if keyID != envelope.KeyID {
		return ErrKeyMismatch
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := decodeCanonicalSignature(envelope.Signature)
	if err != nil || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

layout_identity.text:
// Layout is one node's release root. Owner is the uid that must own every
// directory and file in it; production uses root (0), so the unprivileged
// controller can execute but never replace its own binary.
type Layout struct {
	Root  string
	Owner int
}

// NewLayout returns the production layout owned by root.
func NewLayout(root string) Layout { return Layout{Root: root, Owner: 0} }

func (layout Layout) validate() error {
	if !filepath.IsAbs(layout.Root) || filepath.Clean(layout.Root) != layout.Root || layout.Owner < 0 {
		return fmt.Errorf("%w: release root must be a clean absolute path", ErrInvalid)
	}
	return nil
}

func (layout Layout) releasesPath() string { return filepath.Join(layout.Root, releasesDir) }
func (layout Layout) currentPath() string  { return filepath.Join(layout.Root, currentLink) }
func (layout Layout) activationPath() string {
	return filepath.Join(layout.Root, activationFile)
}
func (layout Layout) knownBadPath() string { return filepath.Join(layout.Root, knownBadFile) }

// ReleaseDir is the directory of one staged release.
func (layout Layout) ReleaseDir(digest string) string {
	return filepath.Join(layout.releasesPath(), digest)
}

// BinaryPath is the executable of one staged release.
func (layout Layout) BinaryPath(digest string) string {
	return filepath.Join(layout.ReleaseDir(digest), BinaryName)
}

// CurrentExecutable is the path the systemd ExecStart line runs.
func (layout Layout) CurrentExecutable() string {
	return filepath.Join(layout.currentPath(), BinaryName)
}

// ensureDirs creates the root and releases directories with exclusive
// ownership and verifies existing ones.
func (layout Layout) ensureDirs() error {
	if err := layout.validate(); err != nil {
		return err
	}
	for _, path := range []string{layout.Root, layout.releasesPath()} {
		// The units run with UMask=0077; set the mode explicitly so the
		// unprivileged controller can traverse to its binary.
		if err := os.Mkdir(path, 0o755); err == nil {
			if err := os.Chmod(path, 0o755); err != nil {
				return err
			}
		} else if !errors.Is(err, os.ErrExist) {
			return err
		}
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	return nil
}

// checkOwned rejects symlinks, foreign owners and group or world write.
func (layout Layout) checkOwned(path string, directory bool) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != layout.Owner || info.Mode().Perm()&0o022 != 0 ||
		directory && !info.IsDir() || !directory && !info.Mode().IsRegular() {
		return fmt.Errorf("%w: %s", ErrUnsafe, path)
	}
	return nil
}

// Current returns the digest the current link points at, or "" when the
// link is absent.
func (layout Layout) Current() (string, error) { return layout.readLink(currentLink) }

// KnownGood returns the digest the known-good link points at, or "" when
// the link is absent: the last release a unit confirmed with a version
// proof. Nothing else moves it, so a restore, an unreadable record or the
// seed never make a release that has not proved itself the delegate.
func (layout Layout) KnownGood() (string, error) { return layout.readLink(knownGoodLink) }

func (layout Layout) readLink(name string) (string, error) {
	if err := layout.validate(); err != nil {
		return "", err
	}
	target, err := os.Readlink(filepath.Join(layout.Root, name))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	digest, ok := strings.CutPrefix(target, releasesDir+"/")
	if !ok || !digestRE.MatchString(digest) {
		return "", fmt.Errorf("%w: %s link target %q", ErrUnsafe, name, target)
	}
	return digest, nil
}

layout_io.text:
func (layout Layout) VerifyRelease(digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: release digest", ErrInvalid)
	}
	for _, path := range []string{layout.Root, layout.releasesPath(), layout.ReleaseDir(digest)} {
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	path := layout.BinaryPath(digest)
	if err := layout.checkOwned(path, false); err != nil {
		return err
	}
	observed, _, err := hashFile(path)
	if err != nil {
		return err
	}
	if observed != digest {
		return fmt.Errorf("%w: release %s bytes changed", ErrUnsafe, digest)
	}
	return nil
}

// flipCurrent atomically repoints the current link at digest.
func (layout Layout) flipCurrent(digest string) error { return layout.flipLink(currentLink, digest) }

func (layout Layout) flipLink(name, digest string) error {
	temporary := filepath.Join(layout.Root, "."+name+"-"+digest[:16])
	_ = os.Remove(temporary)
	if err := os.Symlink(releasesDir+"/"+digest, temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(layout.Root, name)); err != nil {
		_ = os.Remove(temporary)
		return err
	}
	return syncDir(layout.Root)
}

func hashFile(path string) (string, int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", 0, err
	}
	defer file.Close()
	hash := sha256.New()
	size, err := io.Copy(hash, io.LimitReader(file, MaxBinaryBytes+1))
	if err != nil {
		return "", 0, err
	}
	if size > MaxBinaryBytes {
		return "", 0, fmt.Errorf("%w: binary exceeds %d bytes", ErrInvalid, MaxBinaryBytes)
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

func syncDir(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

// writeFileAtomic replaces path with data through a synced temporary file.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, "."+filepath.Base(path)+"-*")
	if err != nil {
		return err
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Chmod(mode); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	return syncDir(directory)
}

// readBounded reads a small regular state file without following a final
// symlink. The open is nonblocking and the opened descriptor must be a
// regular file: a FIFO planted in a controller-writable directory would
// otherwise block the open, and with it every locked update command.
func readBounded(path string, maximum int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%w: %s is not a regular file", ErrInvalid, path)
	}
	data, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%w: %s is too large", ErrInvalid, path)
	}
	return data, nil
}

// Lock serializes the root-run state changes on one node. The ExecStartPre
// prepare step, the watchdog timer and an operator stage or activate can run
// at the same moment; without it two rollbacks race on the current link's
// temporary name and on removing the activation record. The lock is held
// until the returned function is called.
func (layout Layout) Lock() (func(), error) {
	if err := layout.ensureDirs(); err != nil {
		return nil, err
	}
	path := filepath.Join(layout.Root, lockFile)
	fd, err := syscall.Open(path, syscall.O_RDWR|syscall.O_CREAT|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	if err := layout.checkOwned(path, false); err != nil {
		file.Close()
		return nil, err
	}
	for {
		err = syscall.Flock(fd, syscall.LOCK_EX)
		if !errors.Is(err, syscall.EINTR) {
			break
		}
	}
	if err != nil {
		file.Close()
		return nil, &os.PathError{Op: "flock", Path: path, Err: err}
	}
	return func() { file.Close() }, nil
}

seed_install.text:
func Seed(layout Layout, bakedBinary string) (string, error) {
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	current, err := layout.Current()
	if err != nil || current != "" {
		return current, err
	}
	file, err := os.Open(bakedBinary)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > MaxBinaryBytes {
		return "", fmt.Errorf("%w: baked binary", ErrInvalid)
	}
	digest, _, err := hashFile(bakedBinary)
	if err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(digest)); errors.Is(err, os.ErrNotExist) {
		if err := layout.install(file, digest, info.Size(), map[string][]byte{bakedMarkerFile: []byte(bakedBinary + "\n")}); err != nil {
			return "", err
		}
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return "", err
	}
	return digest, layout.flipCurrent(digest)
}

// install writes the binary and metadata into a temporary directory and
// renames it into place, so a release directory is never partially present.
func (layout Layout) install(source io.Reader, digest string, size int64, metadata map[string][]byte) error {
	if !digestRE.MatchString(digest) || size <= 0 || size > MaxBinaryBytes {
		return fmt.Errorf("%w: release identity", ErrInvalid)
	}
	temporary, err := os.MkdirTemp(layout.releasesPath(), ".staging-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(temporary)
	if err := os.Chmod(temporary, 0o755); err != nil {
		return err
	}
	binary, err := os.OpenFile(filepath.Join(temporary, BinaryName), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o500)
	if err != nil {
		return err
	}
	hash := sha256.New()
	written, copyErr := io.Copy(io.MultiWriter(binary, hash), io.LimitReader(source, size+1))
	if copyErr == nil {
		copyErr = binary.Chmod(0o555)
	}
	if copyErr == nil {
		copyErr = binary.Sync()
	}
	if closeErr := binary.Close(); copyErr == nil {
		copyErr = closeErr
	}
	if copyErr != nil {
		return copyErr
	}
	if written != size || hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: staged binary differs from its signed size or digest", ErrInvalid)
	}
	for name, data := range metadata {
		if err := writeSyncedFile(filepath.Join(temporary, name), data, 0o444); err != nil {
			return err
		}
	}
	if err := syncDir(temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, layout.ReleaseDir(digest)); err != nil {
		return err
	}
	if err := syncDir(layout.releasesPath()); err != nil {
		return err
	}
	return layout.VerifyRelease(digest)
}

// writeSyncedFile creates path with data and syncs it before the caller
// syncs and renames the directory, so a crash never keeps a release whose
// metadata files are empty or truncated.
func writeSyncedFile(path string, data []byte, mode os.FileMode) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, mode)
	if err != nil {
		return err
	}
	_, err = file.Write(data)
	if err == nil {
		err = file.Chmod(mode)
	}
	if err == nil {
		err = file.Sync()
	}
	if closeErr := file.Close(); err == nil {
		err = closeErr
	}
	return err
}

activation_read.text:
func (activation Activation) validate() error {
	if activation.Schema != ActivationSchema || !digestRE.MatchString(activation.Target) ||
		!digestRE.MatchString(activation.Previous) || activation.Target == activation.Previous ||
		!entityid.Valid(activation.ActivationID) || !unitRE.MatchString(activation.Unit) ||
		activation.ActivatedAt.IsZero() || !activation.Deadline.After(activation.ActivatedAt) ||
		activation.Deadline.Sub(activation.ActivatedAt) > MaxProofWindow {
		return fmt.Errorf("%w: activation record", ErrInvalid)
	}
	return nil
}

// Pending returns the pending activation, if any.
func (layout Layout) Pending() (Activation, bool, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, false, err
	}
	activation, err := decodeActivation(data)
	if err != nil {
		return Activation{}, false, err
	}
	return activation, true, nil
}

activation_effect.text:
func (layout Layout) pendingRecord() ([]byte, bool, error) {
	if err := layout.checkOwned(layout.activationPath(), false); errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	} else if err != nil {
		return nil, false, err
	}
	data, err := readBounded(layout.activationPath(), maxStateBytes)
	if err != nil {
		return nil, false, err
	}
	return data, true, nil
}

func decodeActivation(data []byte) (Activation, error) {
	var activation Activation
	if err := protocol.DecodeStrict(data, &activation, maxStateBytes); err != nil {
		return Activation{}, fmt.Errorf("%w: activation record: %w", ErrUnreadableActivation, err)
	}
	if err := activation.validate(); err != nil {
		return Activation{}, fmt.Errorf("%w: %w", ErrUnreadableActivation, err)
	}
	return activation, nil
}

// Activate records a pending activation of a staged release and flips the
// current link to it. The caller restarts unit afterwards. A second
// activation is refused while one is pending, unless it is the same target.
// The caller holds Layout.Lock.
func Activate(layout Layout, digest, unit string, now time.Time, window time.Duration) (Activation, error) {
	if window < MinProofWindow || window > MaxProofWindow || !unitRE.MatchString(unit) || now.IsZero() {
		return Activation{}, fmt.Errorf("%w: activation unit or proof window", ErrInvalid)
	}
	// An interrupted rollout restore is finished before the selection
	// changes again, so its recovery can never overwrite this activation.
	if err := layout.finishRestores(); err != nil {
		return Activation{}, err
	}
	if pending, exists, err := layout.Pending(); err != nil {
		return Activation{}, err
	} else if exists {
		if pending.Target == digest && pending.Unit == unit {
			// A retry passes the same gates as a fresh activation: a crash
			// after a rollback marked the target known bad must not
			// re-activate it, and unverified bytes never become current.
			if !now.Before(pending.Deadline) {
				return Activation{}, fmt.Errorf("%w: activation %s passed its deadline; the watchdog resolves it", ErrInvalid, pending.ActivationID)
			}
			if knownBad, err := layout.KnownBad(); err != nil {
				return Activation{}, err
			} else if knownBad[digest] {
				return Activation{}, ErrKnownBad
			}
			if err := layout.VerifyRelease(digest); err != nil {
				return Activation{}, err
			}
			return pending, layout.flipCurrent(digest)
		}
		return Activation{}, fmt.Errorf("%w: activation %s is still pending", ErrInvalid, pending.ActivationID)
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return Activation{}, err
	} else if knownBad[digest] {
		return Activation{}, ErrKnownBad
	}
	previous, err := layout.Current()
	if err != nil {
		return Activation{}, err
	}
	if previous == "" {
		return Activation{}, fmt.Errorf("%w: seed the baked release before activating another", ErrInvalid)
	}
	if previous == digest {
		return Activation{}, fmt.Errorf("%w: release is already current", ErrInvalid)
	}
	for _, release := range []string{previous, digest} {
		if err := layout.VerifyRelease(release); err != nil {
			return Activation{}, err
		}
	}

	activation := Activation{
		Schema: ActivationSchema, ActivationID: entityid.NewAt(now), Unit: unit,
		Target: digest, Previous: previous, ActivatedAt: now.UTC(), Deadline: now.UTC().Add(window),
	}
	encoded, err := protocol.EncodeJSON(activation)
	if err != nil {
		return Activation{}, err
	}
	if err := writeFileAtomic(layout.activationPath(), encoded, 0o644); err != nil {
		return Activation{}, err
	}
	if err := layout.flipCurrent(digest); err != nil {
		return activation, err
	}
	recordActivation(activation)
	return activation, nil
}

knownbad_io.text:
func (layout Layout) KnownBad() (map[string]bool, error) {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]bool{}, nil
	}
	if err != nil {
		return nil, err
	}
	var state knownBadState
	if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
		return nil, err
	}
	known := make(map[string]bool, len(state.Digests))
	for _, digest := range state.Digests {
		if !digestRE.MatchString(digest) {
			return nil, fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
		known[digest] = true
	}
	return known, nil
}

func (layout Layout) markKnownBad(digest string) error {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	var state knownBadState
	switch {
	case errors.Is(err, os.ErrNotExist):
	case err != nil:
		return err
	default:
		if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
			return err
		}
	}
	if slices.Contains(state.Digests, digest) {
		return nil
	}
	state.Digests = append(state.Digests, digest)
	if len(state.Digests) > maxKnownBad {
		state.Digests = state.Digests[len(state.Digests)-maxKnownBad:]
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	return writeFileAtomic(layout.knownBadPath(), encoded, 0o644)
}

restore_io.text:
func (layout Layout) restoreIntentPath(unit string) string {
	return filepath.Join(layout.Root, restoreIntentPrefix+unit+".json")
}

// Restore returns unit to digest, a release it ran before, on a rollout's
// order to roll back the rejected release. Unlike Activate it creates no
// pending activation, so a restore whose restart or proof fails never lets
// the watchdog flip the node back to the rejected release: the node stays on
// digest and the rollout's own deadline decides what happens next.
//
// rejected is marked known bad on this node and a restart obligation for
// unit is recorded before Restore returns, so a failed or interrupted
// restart is retried by the watchdog. A pending activation of rejected over
// digest is rolled back exactly as the watchdog would. Restore reports
// whether it changed anything; it refuses a known-bad or unverifiable
// digest, and a node that runs neither release. The caller holds Lock.
func Restore(layout Layout, digest, rejected, unit string) (bool, error) {
	if !digestRE.MatchString(digest) || !digestRE.MatchString(rejected) || digest == rejected || !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: restore target", ErrInvalid)
	}
	if err := layout.finishRestores(); err != nil {
		return false, err
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return false, err
	} else if knownBad[digest] {
		return false, ErrKnownBad
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return false, err
	}
	activation, pending, err := layout.Pending()
	if err != nil {
		return false, err
	}
	if pending {
		if activation.Unit != unit || activation.Target != rejected || activation.Previous != digest {
			return false, fmt.Errorf("%w: activation %s is pending for another release", ErrInvalid, activation.ActivationID)
		}
		if err := layout.rollback(activation); err != nil {
			return true, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return true, nil
	}
	current, err := layout.Current()
	if err != nil {
		return false, err
	}
	switch current {
	case digest:
		// The unit never left digest, but the rollout rejected the other
		// release: this node must refuse it from now on too. Nothing
		// changed the selection, so no restart is owed.
		return false, layout.markKnownBad(rejected)
	case rejected:
	default:
		return false, fmt.Errorf("%w: the current release is neither the restore target nor the rejected release", ErrInvalid)
	}
	// There is no activation record to recover an interrupted restore
	// from, so a durable intent names the target first; finishRestore
	// completes the switch from it at any later point.
	intent, err := protocol.EncodeJSON(RestoreIntent{Schema: restoreIntentSchema, Unit: unit, Target: digest, Rejected: rejected})
	if err != nil {
		return false, err
	}
	if err := writeFileAtomic(layout.restoreIntentPath(unit), intent, 0o644); err != nil {
		return false, err
	}
	if err := layout.finishRestore(unit); err != nil {
		return true, err
	}
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Actor:   decisionlog.Actor{Slice: "selfupdate"},
		Kind:    decisionlog.KindRollback,
		Subject: memberSubject(unit),
		Summary: "Restored release " + shortDigest(digest) + " on " + unit,
		Reason:  "A rollout rolled back the release this unit ran; that release is now known bad on this node.",
		Rule:    "selfupdate.restore",
		Status:  decisionlog.StatusRolledBack,
		Attrs:   map[string]string{"version": digest, "rejected": rejected},
	})
	return true, nil
}

// finishRestores completes every interrupted restore on this node before
// anything else changes the release selection: Activate, Restore and Watch
// call it first, so a recovered restore can never overwrite a newer
// selection. An intent next to a pending activation cannot be produced by
// these paths; it is refused rather than guessed at. The caller holds Lock.
func (layout Layout) finishRestores() error {
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := layout.finishRestore(intent.Unit); err != nil {
			return err
		}
	}
	return nil
}

// PendingRestores reads owned, strictly validated restore intents without effects.
func (layout Layout) PendingRestores() ([]RestoreIntent, error) {
	if err := layout.validate(); err != nil {
		return nil, err
	}
	if err := layout.checkOwned(layout.Root, true); errors.Is(err, os.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(layout.Root)
	if err != nil {
		return nil, err
	}
	var intents []RestoreIntent
	for _, entry := range entries {
		unit, ok := strings.CutPrefix(entry.Name(), restoreIntentPrefix)
		if !ok {
			continue
		}
		unit, ok = strings.CutSuffix(unit, ".json")
		if !ok || !unitRE.MatchString(unit) {
			return nil, fmt.Errorf("%w: restore intent %q", ErrUnsafe, entry.Name())
		}
		if _, pending, err := layout.Pending(); err != nil {
			return nil, err
		} else if pending {
			return nil, fmt.Errorf("%w: restore intent of %s next to a pending activation", ErrUnsafe, unit)
		}
		intent, err := layout.readRestoreIntent(unit)
		if err != nil {
			return nil, err
		}
		intents = append(intents, intent)
	}
	return intents, nil
}

func (layout Layout) readRestoreIntent(unit string) (RestoreIntent, error) {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); err != nil {
		return RestoreIntent{}, err
	}
	data, err := readBounded(path, maxStateBytes)
	if err != nil {
		return RestoreIntent{}, err
	}
	var intent RestoreIntent
	if err := protocol.DecodeStrict(data, &intent, maxStateBytes); err != nil {
		return RestoreIntent{}, err
	}
	if intent.Schema != restoreIntentSchema || intent.Unit != unit || !digestRE.MatchString(intent.Target) ||
		!digestRE.MatchString(intent.Rejected) || intent.Target == intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: restore intent", ErrInvalid)
	}
	current, err := layout.Current()
	if err != nil {
		return RestoreIntent{}, err
	}
	if current != intent.Target && current != intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: current differs from recorded restore", ErrUnsafe)
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return RestoreIntent{}, err
	}
	if bad[intent.Target] {
		return RestoreIntent{}, ErrKnownBad
	}
	if err := layout.VerifyRelease(intent.Target); err != nil {
		return RestoreIntent{}, fmt.Errorf("restore target cannot be restored: %w", err)
	}
	return intent, nil
}

// finishRestore completes a restore of unit whose intent is recorded: the
// rejected release is known bad, the restart obligation is durable, and
// only then does the link move to the target and the intent go away. Every
// step is idempotent, so it finishes a restore interrupted at any point.
// The caller holds Lock.
func (layout Layout) finishRestore(unit string) error {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	intent, err := layout.readRestoreIntent(unit)
	if err != nil {
		return err
	}
	if err := layout.markKnownBad(intent.Rejected); err != nil {
		return err
	}
	if err := layout.markRestartPending(unit); err != nil {
		return err
	}
	if current, err := layout.Current(); err != nil {
		return err
	} else if current != intent.Target {
		if err := layout.flipCurrent(intent.Target); err != nil {
			return err
		}
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

// MarkRestartPending records that unit still owes a restart, so the
// watchdog retries it until the unit starts. The caller holds Lock.
func (layout Layout) MarkRestartPending(unit string) error {
	return layout.markRestartPending(unit)
}

epoch_io.text:
func (layout Layout) epochPath() string { return filepath.Join(layout.Root, epochFile) }

// AcceptedEpoch returns the newest accepted authority epoch, zero when none.
// The caller holds Lock.
func (layout Layout) AcceptedEpoch() (uint64, error) {
	if err := layout.checkOwned(layout.epochPath(), false); errors.Is(err, os.ErrNotExist) {
		return 0, nil
	} else if err != nil {
		return 0, err
	}
	data, err := readBounded(layout.epochPath(), 64)
	if err != nil {
		return 0, err
	}
	epoch, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil || epoch == 0 {
		return 0, fmt.Errorf("%w: accepted authority epoch", ErrInvalid)
	}
	return epoch, nil
}

// AdmitEpoch durably records epoch as accepted before the caller acts on
// an order from it, and refuses an epoch older than one already accepted.
// The caller holds Lock across AdmitEpoch and the effects it fences.
func (layout Layout) AdmitEpoch(epoch uint64) error {
	if epoch == 0 {
		return fmt.Errorf("%w: authority epoch", ErrInvalid)
	}
	accepted, err := layout.AcceptedEpoch()
	if err != nil {
		return err
	}
	switch {
	case epoch < accepted:
		return ErrStaleEpoch
	case epoch == accepted:
		return nil
	}
	if err := layout.ensureDirs(); err != nil {
		return err
	}
	return writeFileAtomic(layout.epochPath(), fmt.Appendf(nil, "%d\n", epoch), 0o644)
}

restart_io.text:
func (layout Layout) restartMarkerPath(unit string) string {
	return filepath.Join(layout.Root, restartMarkerPrefix+unit)
}

// markRestartPending records that unit must restart onto the restored
// release. It is written before the activation record is removed, so no
// interruption can lose both.
func (layout Layout) markRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	return writeFileAtomic(layout.restartMarkerPath(unit), []byte(unit+"\n"), 0o644)
}

// RestartPending reports whether a rollback of unit has not been followed by
// a restart yet. The caller holds Lock.
func (layout Layout) RestartPending(unit string) (bool, error) {
	if !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: unit", ErrInvalid)
	}
	err := layout.checkOwned(layout.restartMarkerPath(unit), false)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return err == nil, err
}

// ClearRestartPending removes the marker once unit restarted. Prepare calls
// it at every unit start; the watchdog after a successful restart. The caller
// holds Lock.
func (layout Layout) ClearRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	if err := os.Remove(layout.restartMarkerPath(unit)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

executor_tick.text:
// forget resets the leader-local memory and binds it to rolloutID.
func (e *Executor) forget(rolloutID string) {
	e.rolloutID = rolloutID
	e.issued, e.holds, e.paged = map[string]*issue{}, map[string]string{}, map[string]bool{}
}

func (e *Executor) now() time.Time {
	if e.Now != nil {
		return e.Now().UTC()
	}
	return time.Now().UTC()
}

func (e *Executor) freshness() time.Duration {
	if e.ProofFreshness > 0 {
		return e.ProofFreshness
	}
	return DefaultProofFreshness
}

// Run drives the active rollout until ctx ends. Tick errors are logged and
// retried on the next tick: a rollout only ever waits, its deadlines decide.
func (e *Executor) Run(ctx context.Context) error {
	if e.Store == nil || e.Fencer == nil || e.Driver == nil || e.Proofs == nil {
		return fmt.Errorf("%w: rollout executor needs a store, fencer, driver and proof source", ErrInvalid)
	}
	interval := e.Interval
	if interval <= 0 {
		interval = DefaultInterval
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		if err := e.Tick(ctx); err != nil && ctx.Err() == nil {
			slog.WarnContext(ctx, "rollout executor tick failed", "component", "rollout", "error", err)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		case <-e.Wake:
		}
	}
}

// Tick runs one leader-only pass: adopt the active rollout under the
// current epoch, derive its next actions, perform them, and commit the
// events they produced. A follower forgets its leader-local memory.
func (e *Executor) Tick(ctx context.Context) error {
	snapshot := e.Fencer.Current()
	if !snapshot.CanMutate() {
		e.forget("")
		return nil
	}
	if e.issued == nil {
		e.forget("")
	}
	if err := e.Store.RecoverReservation(ctx, snapshot.Epoch); err != nil {
		return err
	}
	record, revision, ok, err := e.Store.Active(ctx)
	if err != nil {
		return err
	}
	if !ok {
		e.forget("")
		if err := e.startNext(ctx, snapshot.Epoch); err != nil {
			e.waiting = err.Error()
			e.publish(snapshot.Epoch, nil)
			return err
		}
		if record, revision, ok, err = e.Store.Active(ctx); err != nil || !ok {
			e.publish(snapshot.Epoch, nil)
			return err
		}
	}
	if record.RolloutID != e.rolloutID {
		e.forget(record.RolloutID)
	}
	if record.AuthorityEpoch != snapshot.Epoch && !record.Phase.Terminal() {
		id := record.RolloutID
		if record, revision, err = e.Store.Adopt(ctx, id, snapshot.Epoch); err != nil {
			return fmt.Errorf("adopt rollout %s: %w", id, err)
		}
	}
	if record.Phase.Terminal() {
		e.forget(record.RolloutID)
		e.publish(snapshot.Epoch, &record)
		return e.Store.Settle(ctx, record, snapshot.Epoch)
	}
	defer func() { e.publish(snapshot.Epoch, &record) }()
	for range maxRounds {
		before := revision
		if record.Phase == rollout.PhasePending {
			if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventStart, At: e.now()}); err != nil {
				return err
			}
		}
		// Deadlines are committed before any effect is derived: a tick
		// that resumes after a deadline rolls back (or freezes) instead of
		// still sending the expired step.
		if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventTick, At: e.now()}); err != nil {
			return err
		}
		if record.Phase.Terminal() {
			break
		}
		events, err := e.act(ctx, record)
		if err != nil {
			return err
		}
		for _, event := range events {
			if err := e.apply(ctx, &record, &revision, event); err != nil {
				return err
			}
		}
		if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventTick, At: e.now()}); err != nil {
			return err
		}
		if revision == before || record.Phase.Terminal() {
			break
		}
	}
	return nil
}

// apply feeds one event to the transition core and commits a changed
// record. An event the core rejects (stale for the current phase, a
// replayed report) is dropped: it was derived from an older record.
func (e *Executor) apply(ctx context.Context, record *rollout.Record, revision *uint64, event rollout.Event) error {
	next, err := rollout.Apply(*record, event)
	if errors.Is(err, rollout.ErrInvalidTransition) || errors.Is(err, rollout.ErrInvalid) || errors.Is(err, rollout.ErrTerminal) {
		slog.DebugContext(ctx, "rollout event dropped", "component", "rollout", "rollout", record.RolloutID,
			"event", event.Kind, "unit", event.Unit, "error", err)
		return nil
	}
	if err != nil {
		return err
	}
	if same, err := sameRecord(*record, next); err != nil || same {
		return err
	}
	committed, err := e.Store.Commit(ctx, *revision, next)
	if committed == 0 {
		return fmt.Errorf("commit rollout %s: %w", record.RolloutID, err)
	}
	if err != nil {
		// The record is committed; the cell slot catches up on a later
		// commit or Settle.
		slog.WarnContext(ctx, "rollout cell slot update is pending", "component", "rollout", "rollout", record.RolloutID, "error", err)
	}
	*record, *revision = next, committed
	return nil
}

func sameRecord(a, b rollout.Record) (bool, error) {
	left, err := protocol.EncodeJSON(a)
	if err != nil {
		return false, err
	}
	right, err := protocol.EncodeJSON(b)
	if err != nil {
		return false, err
	}
	return bytes.Equal(left, right), nil
}

executor_actions.text:
func (e *Executor) act(ctx context.Context, record rollout.Record) ([]rollout.Event, error) {
	var events []rollout.Event
	// A wave is promoted from stored reports when its last unit reports;
	// while a unit that already reported has lost its fresh proof, no
	// healthy report may complete the wave around it.
	lost := e.waveLostProof(record)
	// A unit that restarted during its soak is reported before any other
	// unit can complete the wave from the restarted unit's stored reports.
	if restart := e.waveRestart(record); restart != nil {
		return []rollout.Event{*restart}, nil
	}
	// A unit an earlier wave promoted that now proves another release
	// rolls the rollout back before any later wave moves or completes.
	if regressed := e.promotedRegression(record); regressed != nil {
		return []rollout.Event{*regressed}, nil
	}
	for _, action := range rollout.NextActions(record) {
		var event *rollout.Event
		var err error
		switch action.Kind {
		case rollout.ActionPreflight:
			event = e.preflight(ctx, record)
		case rollout.ActionPrepare:
			event, err = e.prepare(ctx, record, action)
		case rollout.ActionAwaitHealth:
			event = e.awaitHealth(record, action)
			if event != nil && event.Kind == rollout.EventHealthy && lost != "" {
				e.hold(record, "soak", "unit "+lost+" stopped proving it serves the target")
				event = nil
			} else if event != nil && event.Kind == rollout.EventHealthy {
				e.release(record, "soak")
			}
		case rollout.ActionRollback:
			event, err = e.rollback(ctx, record, action)
		case rollout.ActionPage:
			e.page(record)
		}
		if err != nil {
			// Events observed before the fence failed are dropped with
			// it: the successor derives them again.
			return nil, err
		}
		if event != nil {
			events = append(events, *event)
		}
	}
	return events, nil
}

func (e *Executor) preflight(ctx context.Context, record rollout.Record) *rollout.Event {
	if reason := e.checkGate(ctx, record, ""); reason != "" {
		e.hold(record, "", reason)
		return nil
	}
	now := e.now()
	for _, unit := range sortedUnits(record) {
		proof, ok := e.Proofs.Latest(unit)
		if !ok || !e.fresh(proof) {
			e.hold(record, "", "unit "+unit+" has no fresh health proof")
			return nil
		}
		if proof.BinarySHA256 != record.FromDigest {
			e.release(record, "")
			return &rollout.Event{Kind: rollout.EventPreflightFailed, At: now,
				Reason: fmt.Sprintf("unit %s serves %s, not the rollout's from digest", unit, short(proof.BinarySHA256))}
		}
	}
	e.release(record, "")
	return &rollout.Event{Kind: rollout.EventPreflightPassed, At: now}
}

func (e *Executor) prepare(ctx context.Context, record rollout.Record, action rollout.Action) (*rollout.Event, error) {
	if reason := e.peersServing(ctx, record, action.Peers); reason != "" {
		e.hold(record, action.Unit, reason)
		return nil, nil
	}
	if reason := e.checkGate(ctx, record, action.Unit); reason != "" {
		e.hold(record, action.Unit, reason)
		return nil, nil
	}
	if e.expired(action) {
		return nil, nil
	}
	if err := e.fence(ctx, record); err != nil {
		return nil, err
	}
	step := e.track(stepKey(record.RolloutID, action.Unit, StepPrepare), action.Unit)
	if !step.accepted {
		// Each attempt until one is accepted re-reads the unit's
		// incarnation: a restart between an undelivered attempt and the
		// accepted one was not caused by the step and must not count as
		// the unit coming back on the wrong binary.
		step.before, step.known = e.Proofs.Latest(action.Unit)
		step.at = e.now()
	}
	reply, err := e.Driver.Step(ctx, Step{RolloutID: record.RolloutID, Kind: record.Kind, Unit: action.Unit,
		OperationID: action.OperationID, Action: StepPrepare, Digest: action.Digest, Replaces: record.FromDigest,
		Epoch:       record.AuthorityEpoch,
		ProofWindow: time.Duration(record.Policy.ProofDeadlineSeconds) * time.Second,
		Deadline:    action.Deadline,
		Fence:       func(ctx context.Context) error { return e.fence(ctx, record) }})
	switch {
	case errors.Is(err, ErrLeaseLost):
		return nil, err
	case err != nil:
		slog.WarnContext(ctx, "rollout step was not delivered", "component", "rollout", "rollout", record.RolloutID,
			"unit", action.Unit, "error", err)
		e.hold(record, action.Unit, "the unit's step agent did not answer")
		return nil, nil
	case reply.Outcome.Accepted():
		e.release(record, action.Unit)
		if !step.accepted {
			step.accepted = true
			recordStep(record, action.Unit, StepPrepare, reply.Outcome)
		}
		return &rollout.Event{Kind: rollout.EventPrepared, Unit: action.Unit, At: e.now()}, nil
	case reply.Outcome == OutcomeRefused:
		e.release(record, action.Unit)
		return &rollout.Event{Kind: rollout.EventHeld, Unit: action.Unit, At: e.now(),
			Reason: "unit " + action.Unit + " refused the step: " + reply.Reason}, nil
	default:
		e.hold(record, action.Unit, "the unit asked to retry: "+reply.Reason)
		return nil, nil
	}
}

func (e *Executor) awaitHealth(record rollout.Record, action rollout.Action) *rollout.Event {
	proof, ok := e.Proofs.Latest(action.Unit)
	key := stepKey(record.RolloutID, action.Unit, StepPrepare)
	if _, remembered := e.issued[key]; !remembered && ok {
		// A successor leader, which never saw the step, takes the first
		// incarnation it sees as the baseline: a later incarnation on
		// another release is the unit coming back on the wrong binary.
		// When that first incarnation already is one, the proof deadline
		// still rolls the rollout back.
		e.issued[key] = &issue{at: e.now(), before: proof, known: true, accepted: true}
	}
	// Only a fresh proof completes anything: a cached one cannot supply a
	// soak report for a unit that has since stopped serving.
	if !ok || proof.seen().Before(record.PhaseStartedAt) || !e.fresh(proof) {
		return nil
	}
	if proof.BinarySHA256 == record.ToDigest {
		progress := record.Units[action.Unit]
		if progress.HealthyReports > 0 && !proof.seen().After(progress.LastHealthyAt) {
			return nil
		}
		return &rollout.Event{Kind: rollout.EventHealthy, Unit: action.Unit, Health: proof.Health(), At: e.now()}
	}
	// A new incarnation that serves another release after the step means
	// the unit came back on the wrong binary (for example the watchdog
	// rolled it back). The old process's proofs, sent before it restarted,
	// are ignored by the incarnation check.
	step, known := e.issued[key]
	if known && step.known && !proof.sameIncarnation(step.before) && proof.arrivedAfter(step.at) {
		return &rollout.Event{Kind: rollout.EventUnhealthy, Unit: action.Unit, At: e.now(),
			Reason: fmt.Sprintf("unit %s restarted serving %s instead of the target", action.Unit, short(proof.BinarySHA256))}
	}
	return nil
}

func (e *Executor) rollback(ctx context.Context, record rollout.Record, action rollout.Action) (*rollout.Event, error) {
	key := stepKey(record.RolloutID, action.Unit, StepRollback) + "/" + action.OperationID
	step, sent := e.issued[key]
	if !sent || !step.accepted {
		if reason := e.peersServing(ctx, record, action.Peers); reason != "" {
			e.hold(record, action.Unit, reason)
			return nil, nil
		}
		if reason := e.checkGate(ctx, record, action.Unit); reason != "" {
			e.hold(record, action.Unit, reason)
			return nil, nil
		}
		if e.expired(action) {
			return nil, nil
		}
		if err := e.fence(ctx, record); err != nil {
			return nil, err
		}
		step = e.track(key, action.Unit)
		reply, err := e.Driver.Step(ctx, Step{RolloutID: record.RolloutID, Kind: record.Kind, Unit: action.Unit,
			OperationID: action.OperationID, Action: StepRollback, Digest: action.Digest, Replaces: record.ToDigest,
			Epoch: record.AuthorityEpoch, ProofWindow: time.Duration(record.Policy.RollbackDeadlineSeconds) * time.Second,
			Deadline: action.Deadline,
			Fence:    func(ctx context.Context) error { return e.fence(ctx, record) }})
		switch {
		case errors.Is(err, ErrLeaseLost):
			return nil, err
		case err != nil:
			slog.WarnContext(ctx, "rollout rollback step was not delivered", "component", "rollout", "rollout", record.RolloutID,
				"unit", action.Unit, "error", err)
			e.hold(record, action.Unit, "the unit's step agent did not answer")
			return nil, nil
		case reply.Outcome == OutcomeRefused:
			e.release(record, action.Unit)
			return &rollout.Event{Kind: rollout.EventRollbackHeld, Unit: action.Unit, At: e.now(),
				Reason: "unit " + action.Unit + " refused its rollback: " + reply.Reason}, nil
		case !reply.Outcome.Accepted():
			e.hold(record, action.Unit, "the unit asked to retry its rollback: "+reply.Reason)
			return nil, nil
		}
		e.release(record, action.Unit)
		step.accepted = true
		// Only a proof observed after the accepted attempt returned speaks
		// for the process it left running; a proof cached from an earlier,
		// failed attempt does not.
		step.at = e.now()
		recordStep(record, action.Unit, StepRollback, reply.Outcome)
	}
	proof, ok := e.Proofs.Latest(action.Unit)
	if ok && proof.BinarySHA256 == record.FromDigest && proof.arrivedAfter(step.at) && e.fresh(proof) {
		return &rollout.Event{Kind: rollout.EventRollbackServing, Unit: action.Unit, At: e.now()}, nil
	}
	return nil, nil
}

// fence re-checks the authority lease immediately before a step leaves the
// leader: a lease lost while earlier steps, gates or reads ran must not
// still move a unit. Store.Commit fences the record, not this effect.
func (e *Executor) fence(ctx context.Context, record rollout.Record) error {
	if err := e.Fencer.Guard(ctx, record.AuthorityEpoch); err != nil {
		return fmt.Errorf("%w: %w", ErrLeaseLost, err)
	}
	return nil
}

executor_proof_guards.text:
func (e *Executor) waveLostProof(record rollout.Record) string {
	if record.WaveIndex < 0 || record.WaveIndex >= len(record.Waves) {
		return ""
	}
	for _, id := range sortedUnits(record) {
		progress := record.Units[id]
		if progress.State != rollout.UnitPromoted && (progress.State != rollout.UnitSoaking || progress.HealthyReports == 0) {
			continue
		}
		if proof, ok := e.Proofs.Latest(id); !ok || !e.fresh(proof) || proof.BinarySHA256 != record.ToDigest {
			return id
		}
	}
	return ""
}

// waveRestart returns the healthy report of a soaking unit of the current
// wave whose fresh proof comes from a new incarnation; the transition core
// rolls the rollout back on it.
func (e *Executor) waveRestart(record rollout.Record) *rollout.Event {
	if !forwardPhase(record.Phase) {
		return nil
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		if progress.State != rollout.UnitSoaking || progress.HealthyReports == 0 {
			continue
		}
		proof, ok := e.Proofs.Latest(id)
		if ok && e.fresh(proof) && !proof.seen().Before(record.PhaseStartedAt) &&
			(proof.ProcessID != progress.ProcessID || proof.StartNonce != progress.StartNonce) {
			return &rollout.Event{Kind: rollout.EventHealthy, Unit: id, Health: proof.Health(), At: e.now()}
		}
	}
	return nil
}

// promotedRegression reports an unhealthy event for a unit that an earlier
// wave promoted but whose fresh proof, newer than its last healthy report,
// serves another release than the target. A unit without a fresh proof is
// judged by the peer checks of the steps around it instead.
func (e *Executor) promotedRegression(record rollout.Record) *rollout.Event {
	if !forwardPhase(record.Phase) {
		return nil
	}
	for _, id := range sortedUnits(record) {
		progress := record.Units[id]
		if progress.State != rollout.UnitPromoted {
			continue
		}
		proof, ok := e.Proofs.Latest(id)
		if ok && e.fresh(proof) && proof.seen().After(progress.LastHealthyAt) && proof.BinarySHA256 != record.ToDigest {
			return &rollout.Event{Kind: rollout.EventUnhealthy, Unit: id, At: e.now(),
				Reason: fmt.Sprintf("promoted unit %s now serves %s instead of the target", id, short(proof.BinarySHA256))}
		}
	}
	return nil
}

func forwardPhase(phase rollout.Phase) bool {
	return phase == rollout.PhaseCanary || phase == rollout.PhaseCanarySoak ||
		phase == rollout.PhaseBatch || phase == rollout.PhaseBatchSoak
}

// expired reports a step whose phase deadline passed while its gates ran;
// the next tick commits the deadline instead of sending it.
func (e *Executor) expired(action rollout.Action) bool {
	return !action.Deadline.IsZero() && !e.now().Before(action.Deadline)
}

// fresh requires the proof to have reached the leader within the
// freshness limit, on the leader's clock, and its signed observation time
// to be no older than that limit plus the verified clock skew, so neither
// a unit clock behind the leader's nor a late delivery of an old proof
// decides it.
func (e *Executor) fresh(proof HealthProof) bool { return isFresh(proof, e.now(), e.freshness()) }

func isFresh(proof HealthProof, now time.Time, freshness time.Duration) bool {
	return now.Sub(proof.seen()) <= freshness && now.Sub(proof.ObservedAt) <= freshness+healthClockSkew
}

executor_program_status.text:
func (e *Executor) page(record rollout.Record) {
	if e.paged[record.RolloutID] {
		return
	}
	e.paged[record.RolloutID] = true
	slog.Error("rollout is frozen and needs an operator", "component", "rollout", "rollout", record.RolloutID,
		"kind", record.Kind, "reason", record.Reason)
}

// track returns the leader-local memory of a step, creating it with the
// unit's proof from before the step.
func (e *Executor) track(key, unit string) *issue {
	if step, exists := e.issued[key]; exists {
		return step
	}
	before, known := e.Proofs.Latest(unit)
	step := &issue{at: e.now(), before: before, known: known}
	e.issued[key] = step
	return step
}

func stepKey(rolloutID, unit string, action StepAction) string {
	return rolloutID + "/" + unit + "/" + string(action)
}

// peersServing requires a fresh proof from every group peer, on either
// side of the rollout, so a step never takes a second replica down. A peer
// the rollout does not step (pending or rolled back) may serve a third
// release an operator installed by hand, unless the cell knows it bad.
func (e *Executor) peersServing(ctx context.Context, record rollout.Record, peers []string) string {
	for _, peer := range peers {
		proof, ok := e.Proofs.Latest(peer)
		if !ok || !e.fresh(proof) {
			return "group peer " + peer + " is not serving"
		}
		digest := proof.BinarySHA256
		if digest == record.FromDigest || digest == record.ToDigest {
			continue
		}
		state := record.Units[peer].State
		if state != rollout.UnitPending && state != rollout.UnitRolledBack || slices.Contains(record.KnownBad, digest) {
			return "group peer " + peer + " is not serving"
		}
		// The record keeps a bounded list; the store has every rejected
		// digest. A failed read holds the step.
		if bad, err := e.Store.IsKnownBad(ctx, digest); err != nil || bad {
			return "group peer " + peer + " serves a release the cell may know bad"
		}
	}
	return ""
}

func (e *Executor) checkGate(ctx context.Context, record rollout.Record, unit string) string {
	if e.Gate == nil {
		return ""
	}
	if err := e.Gate.Check(ctx, record, unit); err != nil {
		return err.Error()
	}
	return ""
}

// startNext begins the first program rollout that has not completed. A
// program stops at a rollout that ended any other way.
func (e *Executor) startNext(ctx context.Context, epoch uint64) error {
	e.waiting = ""
	if e.Program == nil {
		return nil
	}
	program, err := e.Program(ctx)
	if err != nil {
		return fmt.Errorf("read rollout program: %w", err)
	}
	for _, spec := range program {
		existing, _, err := e.Store.Load(ctx, spec.RolloutID)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			now := e.now()
			if spec.StartedAt.After(now) {
				e.waiting = fmt.Sprintf("the release is issued at %s; waiting for the cell clock", spec.StartedAt)
				return nil
			}
			spec.AuthorityEpoch = epoch
			if _, _, err := e.Store.Begin(ctx, spec, now); err != nil {
				return fmt.Errorf("begin rollout %s: %w", spec.RolloutID, err)
			}
			return nil
		}
		if err != nil {
			return e.halt(spec.RolloutID, err.Error())
		}
		// A completed record only satisfies the program step it was
		// planned from: the same ID with another target, kind, waves or
		// policy stops the program instead of skipping ahead.
		if err := existing.Matches(spec); err != nil {
			return e.halt(spec.RolloutID, err.Error())
		}
		if existing.Phase != rollout.PhaseComplete {
			return e.halt(spec.RolloutID, "rollout ended "+string(existing.Phase))
		}
	}
	return nil
}

func (e *Executor) halt(rolloutID, reason string) error {
	e.waiting = "rollout " + rolloutID + " stopped the program: " + reason
	if e.halted != rolloutID {
		e.halted = rolloutID
		slog.Warn("rollout program stopped", "component", "rollout", "rollout", rolloutID, "reason", reason)
	}
	return nil
}

func (e *Executor) publish(epoch uint64, record *rollout.Record) {
	if e.Status == nil {
		return
	}
	status := statusOf(e.Cell, epoch, record, e.Proofs, e.holds, e.now())
	if record == nil {
		status.Waiting = e.waiting
	}
	e.Status.PublishStatus(status)
}

func sortedUnits(record rollout.Record) []string {
	var units []string
	for _, wave := range record.Waves {
		units = append(units, wave...)
	}
	return units
}

func short(digest string) string {
	if len(digest) > 12 {
		return digest[:12]
	}
	return digest
}

proof_time.text:
const (
	HealthDomain = "terrascale.orchestrator.rollout-health"
	HealthSchema = "terrascale.orchestrator.rollout-health.v1"
	// HealthLifetime bounds one proof, so only a recent one counts.
	HealthLifetime = 2 * time.Minute
	// DefaultProofInterval is how often a healthy unit publishes a proof.
	DefaultProofInterval = 5 * time.Second
	healthClockSkew      = time.Minute
	// incarnationQuiet is how long a unit's newest incarnation must have
	// been silent before a new incarnation whose clock reads earlier
	// replaces it: a live incarnation keeps proving within it, so a
	// delayed proof of a superseded process never displaces it.
	incarnationQuiet = 2 * DefaultProofInterval
	maxProofUnits    = 4 * rollout.MaxUnits
	// maxRetired bounds the superseded incarnations kept per unit.
	maxRetired = 8
	// retiredFor is how long a superseded incarnation stays refused: no
	// proof it signed can still verify after that.
	retiredFor = HealthLifetime + healthClockSkew
)

var (
	ErrInvalid = errors.New("rollout executor input is invalid")

	unitRE   = regexp.MustCompile(`^[a-z0-9][a-z0-9_.-]{0,127}$`)
	nonceRE  = regexp.MustCompile(`^[0-9a-f]{32}$`)
	digestRE = regexp.MustCompile(`^[0-9a-f]{64}$`)
)

// HealthProof is signed by a running unit while it is healthy. It names the
// exact binary digest the process executes and its incarnation (process ID
// and a per-start nonce), so the executor detects both a wrong release and
// a restart during soak.
type HealthProof struct {
	Schema       string    `json:"schema"`
	Cell         string    `json:"cell"`
	Unit         string    `json:"unit"`
	BinarySHA256 string    `json:"binary_sha256"`
	ProcessID    int64     `json:"process_id"`
	StartNonce   string    `json:"start_nonce"`
	ObservedAt   time.Time `json:"observed_at"`
	// ReceivedAt is when the collector accepted the proof, on the leader's
	// own clock. It is never signed or sent; it orders a proof against the
	// leader's steps without trusting the unit's clock.
	ReceivedAt time.Time `json:"-"`
}

func (proof HealthProof) validate() error {
	if proof.Schema != HealthSchema || !unitRE.MatchString(proof.Cell) || !unitRE.MatchString(proof.Unit) ||
		!digestRE.MatchString(proof.BinarySHA256) || proof.ProcessID <= 0 || !nonceRE.MatchString(proof.StartNonce) ||
		proof.ObservedAt.IsZero() {
		return fmt.Errorf("%w: health proof", ErrInvalid)
	}
	return nil
}

// Health converts the proof into the rollout core's health observation.
// Its ObservedAt is the leader's receipt time (seen), so the core orders
// the report against the leader-clock phase and soak times without
// trusting the unit's clock; the signed ObservedAt only bounds replay.
func (proof HealthProof) Health() rollout.Health {
	return rollout.Health{Digest: proof.BinarySHA256, ProcessID: proof.ProcessID, StartNonce: proof.StartNonce,
		ObservedAt: proof.seen()}
}

// seen is when the proof reached the leader, on the leader's clock. A
// source that does not record receipt falls back to the unit's own
// observation time.
func (proof HealthProof) seen() time.Time {
	if !proof.ReceivedAt.IsZero() {
		return proof.ReceivedAt
	}
	return proof.ObservedAt
}

// arrivedAfter reports whether the proof reached the leader after at, a
// leader-clock time.
func (proof HealthProof) arrivedAfter(at time.Time) bool {
	return proof.seen().After(at)
}

func (proof HealthProof) sameIncarnation(other HealthProof) bool {
	return proof.ProcessID == other.ProcessID && proof.StartNonce == other.StartNonce
}

unit_planning.text:
func ControllerUnits(controllers []string, seed string) ([]rollout.Unit, error) {
	if seed != "" && !slices.Contains(controllers, seed) {
		return nil, fmt.Errorf("%w: seed controller %q is not a controller", ErrInvalid, seed)
	}
	units := make([]rollout.Unit, 0, len(controllers))
	for _, id := range controllers {
		units = append(units, rollout.Unit{ID: id, Group: ControllerGroup, Seed: id == seed})
	}
	return units, nil
}

// HostUnits returns the host units of a cell from the TerraBase partitions
// each host serves a seat of. Hosts that share a partition, directly or
// through other hosts, share a group, so a wave never takes two seats of
// one partition. A host without seats is its own group.
func HostUnits(partitions map[string][]string) []rollout.Unit {
	hosts := slices.Sorted(maps.Keys(partitions))
	parent := make(map[string]string, len(hosts))
	var find func(string) string
	find = func(host string) string {
		if parent[host] == host {
			return host
		}
		root := find(parent[host])
		parent[host] = root
		return root
	}
	for _, host := range hosts {
		parent[host] = host
	}
	owner := map[string]string{}
	for _, host := range hosts {
		for _, partition := range partitions[host] {
			first, seen := owner[partition]
			if !seen {
				owner[partition] = host
				continue
			}
			a, b := find(first), find(host)
			if a != b {
				// Keep the smallest host as the root so the group name
				// depends only on the input set.
				parent[max(a, b)] = min(a, b)
			}
		}
	}
	units := make([]rollout.Unit, 0, len(hosts))
	for _, host := range hosts {
		sum := sha256.Sum256([]byte(find(host)))
		units = append(units, rollout.Unit{ID: host, Group: "hosts-" + hex.EncodeToString(sum[:8])})
	}
	return units
}

// Program is an ordered list of rollouts. The executor starts each one only
// after the previous one completed, so the controllers finish before any
// host moves, and stops the program at the first rollout that did not
// complete (rolled back, aborted).
type Program []rollout.Spec

// SelfUpdateProgram returns the controller rollout followed by the host
// rollout of one orchestrator release. Rollout IDs are derived from id.
func SelfUpdateProgram(id, cell, from, to string, controllers []rollout.Unit, hosts []rollout.Unit,
	policy rollout.Policy,
) Program {
	var program Program
	if len(controllers) > 0 {
		program = append(program, rollout.Spec{RolloutID: entityid.Derive(rollout.ControllerReleaseDomain, id), Kind: rollout.KindController, Cell: cell,
			FromDigest: from, ToDigest: to, Units: controllers, Policy: policy})
	}
	if len(hosts) > 0 {
		program = append(program, rollout.Spec{RolloutID: entityid.Derive(rollout.HostReleaseDomain, id), Kind: rollout.KindHost, Cell: cell,
			FromDigest: from, ToDigest: to, Units: hosts, Policy: policy})
	}
	return program
}

executor_holds.text:
func unitSubject(record rollout.Record, unit string) decisionlog.Subject {
	return decisionlog.Subject{Kind: "member", ID: unit, Name: string(record.Kind) + "/" + record.RolloutID}
}

func holdKey(unit string) string {
	if unit == "" {
		return "preflight"
	}
	return unit
}

// hold records that a step for unit ("" is preflight) waits on reason.
func (e *Executor) hold(record rollout.Record, unit, reason string) {
	key := holdKey(unit)
	if e.holds[key] == reason {
		return
	}
	e.holds[key] = reason
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Region:   record.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     decisionlog.KindHeld,
		Subject:  unitSubject(record, key),
		Summary:  "Held the " + string(record.Phase) + " step of " + key + " in rollout " + record.RolloutID,
		Reason:   reason,
		Rule:     "rollout.executor.gate",
		Status:   decisionlog.StatusPending,
		Epoch:    record.AuthorityEpoch,
		ParentID: decisionlog.Correlated(rollout.ReleaseCorrelation(record.ToDigest)),
		Attrs:    map[string]string{"rollout": record.RolloutID, "phase": string(record.Phase)},
	})
	slog.Info("rollout step held", "component", "rollout", "rollout", record.RolloutID, "unit", key, "reason", reason)
}

// release clears a hold of unit once its step proceeds.
func (e *Executor) release(record rollout.Record, unit string) {
	key := holdKey(unit)
	if _, held := e.holds[key]; !held {
		return
	}
	delete(e.holds, key)
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Region:   record.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     decisionlog.KindHoldCleared,
		Subject:  unitSubject(record, key),
		Summary:  "Released the " + string(record.Phase) + " step of " + key + " in rollout " + record.RolloutID,
		Reason:   "Its gate and group peers are healthy again.",
		Rule:     "rollout.executor.gate",
		Status:   decisionlog.StatusSucceeded,
		Epoch:    record.AuthorityEpoch,
		ParentID: decisionlog.Correlated(rollout.ReleaseCorrelation(record.ToDigest)),
		Attrs:    map[string]string{"rollout": record.RolloutID, "phase": string(record.Phase)},
	})
}

// recordStep journals a unit step the unit's agent accepted.
func recordStep(record rollout.Record, unit string, action StepAction, outcome StepOutcome) {
	kind, summary, digest := decisionlog.KindStageChanged, "Moved "+unit+" to the target release", record.ToDigest
	if action == StepRollback {
		kind, summary, digest = decisionlog.KindRollback, "Returned "+unit+" to the previous release", record.FromDigest
	}
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Region:   record.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     kind,
		Subject:  unitSubject(record, unit),
		Summary:  summary + " in rollout " + record.RolloutID,
		Reason:   "The unit's group peers were serving and the cluster gate passed.",
		Rule:     "rollout.executor." + string(action),
		Status:   decisionlog.StatusInProgress,
		Epoch:    record.AuthorityEpoch,
		ParentID: decisionlog.Correlated(rollout.ReleaseCorrelation(record.ToDigest)),
		Attrs: map[string]string{"rollout": record.RolloutID, "digest": digest, "outcome": string(outcome),
			"phase": string(record.Phase)},
	})
}

status_derive.text:
func statusOf(cell string, epoch uint64, record *rollout.Record, proofs ProofSource, holds map[string]string,
	now time.Time,
) Status {
	status := Status{Schema: StatusSchema, Cell: cell, Epoch: epoch, UpdatedAt: now.UTC()}
	if record == nil {
		return status
	}
	status.Active = record.Phase.Active()
	status.RolloutID, status.Kind, status.Phase = record.RolloutID, record.Kind, record.Phase
	status.Wave, status.Waves = record.WaveIndex+1, len(record.Waves)
	status.FromDigest, status.ToDigest, status.Reason = record.FromDigest, record.ToDigest, record.Reason
	status.PhaseDeadline = record.PhaseDeadline
	if len(holds) > 0 {
		status.Holds = make(map[string]string, len(holds))
		for unit, reason := range holds {
			status.Holds[unit] = reason
		}
	}
	for id, progress := range record.Units {
		unit := UnitStatus{ID: id, Group: progress.Group, Seed: progress.Seed, Wave: progress.Wave, State: progress.State}
		if proofs != nil {
			if proof, ok := proofs.Latest(id); ok {
				unit.Digest, unit.ProofAt = proof.BinarySHA256, proof.ObservedAt
			}
		}
		status.Units = append(status.Units, unit)
	}
	slices.SortFunc(status.Units, func(a, b UnitStatus) int {
		if a.Wave != b.Wave {
			return a.Wave - b.Wave
		}
		if a.ID < b.ID {
			return -1
		}
		if a.ID > b.ID {
			return 1
		}
		return 0
	})
	return status
}

store_open.text:
func OpenStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || fencer == nil || !tokenRE.MatchString(cell) || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: rollout store configuration", ErrInvalid)
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: Bucket, Storage: jetstream.FileStorage, Replicas: replicas, History: 8, MaxValueSize: maxRecordBytes,
	})
	if err != nil {
		return nil, fmt.Errorf("rollout store: %w", err)
	}
	return &Store{kv: kv, fencer: fencer, cell: cell}, nil
}

store_read.text:
func (s *Store) recordKnownBad(ctx context.Context, epoch uint64, digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: known-bad digest", ErrInvalid)
	}
	encoded, err := protocol.EncodeJSON(knownBadEntry{Digest: digest})
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if _, err := s.kv.Create(ctx, knownBadKey(digest), encoded); err != nil && !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("record known-bad digest: %w", err)
	}
	return nil
}

// knownBad reports whether digest is known bad in the cell list or in its
// durable per-digest record.
func (s *Store) knownBad(ctx context.Context, state CellState, digest string) (bool, error) {
	if slices.Contains(state.KnownBad, digest) {
		return true, nil
	}
	_, err := s.kv.Get(ctx, knownBadKey(digest))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("read known-bad digest: %w", err)
	}
	return true, nil
}

// Cell returns the cell slot and its revision (zero when absent).
func (s *Store) Cell(ctx context.Context) (CellState, uint64, error) {
	entry, err := s.kv.Get(ctx, cellKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return CellState{SchemaVersion: SchemaVersion, Cell: s.cell}, 0, nil
	}
	if err != nil {
		return CellState{}, 0, err
	}
	var state CellState
	if err := protocol.DecodeTolerant(entry.Value(), &state, maxRecordBytes); err != nil {
		return CellState{}, 0, err
	}
	if err := state.validate(s.cell); err != nil {
		return CellState{}, 0, err
	}
	return state, entry.Revision(), nil
}

// Load returns a rollout record and its KV revision.
func (s *Store) Load(ctx context.Context, rolloutID string) (Record, uint64, error) {
	if !entityid.Valid(rolloutID) {
		return Record{}, 0, fmt.Errorf("%w: rollout ID", ErrInvalid)
	}
	entry, err := s.kv.Get(ctx, rolloutKey(rolloutID))
	if err != nil {
		return Record{}, 0, err
	}
	// Records decode tolerantly, so a marker would decode as an empty record:
	// read it first. A record always has a schema version and a marker never
	// does, so a newer binary's members change neither.
	if marker, err := decodeAbandoned(entry.Value(), rolloutID); err != nil {
		return Record{}, 0, err
	} else if marker != nil {
		return Record{}, 0, marker
	}
	var record Record
	if err := protocol.DecodeTolerant(entry.Value(), &record, maxRecordBytes); err != nil {
		return Record{}, 0, err
	}
	if err := record.Validate(); err != nil {
		return Record{}, 0, err
	}
	if record.Cell != s.cell || record.RolloutID != rolloutID {
		return Record{}, 0, fmt.Errorf("%w: stored rollout scope", ErrInvalid)
	}
	return record, entry.Revision(), nil
}

store_begin.text:
func (s *Store) Begin(ctx context.Context, spec Spec, now time.Time) (Record, uint64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if spec.Cell != s.cell {
		return Record{}, 0, fmt.Errorf("%w: rollout cell", ErrInvalid)
	}
	if err := s.fencer.Guard(ctx, spec.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	// An ID already bound to another rollout is refused before the cell
	// slot is reserved or the target's attempt is counted.
	bound := false
	if existing, _, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		bound = true
	} else if errors.Is(err, ErrAbandonedRollout) {
		if err := s.releaseSlot(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
			return Record{}, 0, err
		}
		return Record{}, 0, ErrAbandonedRollout
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	if !bound {
		if release, kind, found, err := s.releaseStage(ctx, spec.RolloutID); err != nil {
			return Record{}, 0, err
		} else if found && (spec.ToDigest != release.Digest || spec.Kind != kind ||
			!spec.StartedAt.IsZero() && !spec.StartedAt.Equal(release.CreatedAt)) {
			return Record{}, 0, fmt.Errorf("%w: release stage binding", ErrConflict)
		} else if found {
			spec.StartedAt = release.CreatedAt
			bound = true
		}
	}
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return Record{}, 0, err
		}
		if state.ActiveRolloutID == spec.RolloutID {
			// Only an existing immutable record can resume the same ID.
			if _, _, err := s.Load(ctx, spec.RolloutID); errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				if err := s.abandon(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
					return Record{}, 0, err
				}
				if err := s.releaseSlot(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
					return Record{}, 0, err
				}
				return Record{}, 0, ErrAbandonedRollout
			} else if err != nil {
				return Record{}, 0, err
			}
			return s.createRecord(ctx, spec, state, now)
		}
		if state.ActiveRolloutID != "" {
			// A terminal commit whose cell release was interrupted is
			// repaired here; a live rollout keeps the slot.
			active, _, err := s.Load(ctx, state.ActiveRolloutID)
			if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				// The slot was claimed but its record was never created (a
				// crash or failure between the two writes). Abandon the ID
				// so a late create of it fails, then release the slot.
				if err := s.abandon(ctx, spec.AuthorityEpoch, state.ActiveRolloutID); err != nil {
					return Record{}, 0, err
				}
				if err := s.releaseSlot(ctx, spec.AuthorityEpoch, state.ActiveRolloutID); err != nil {
					return Record{}, 0, err
				}
				continue
			}
			if err != nil {
				return Record{}, 0, fmt.Errorf("load active rollout %q: %w", state.ActiveRolloutID, err)
			}
			if !active.Phase.Terminal() {
				return Record{}, 0, ErrActiveRollout
			}
			if err := s.syncCell(ctx, withEpoch(active, spec.AuthorityEpoch)); err != nil {
				return Record{}, 0, err
			}
			continue
		}
		if !bound {
			return Record{}, 0, fmt.Errorf("%w: rollout needs a published release stage", ErrNoRelease)
		}
		if bad, err := s.knownBad(ctx, state, spec.ToDigest); err != nil {
			return Record{}, 0, err
		} else if bad {
			return Record{}, 0, ErrKnownBad
		}
		if bad, err := s.knownBad(ctx, state, spec.FromDigest); err != nil {
			return Record{}, 0, err
		} else if bad {
			return Record{}, 0, fmt.Errorf("%w: rollback target digest is known bad", ErrInvalid)
		}
		maxAttempts := spec.Policy.MaxAttempts
		if state.Attempts[spec.ToDigest] >= maxAttempts {
			return Record{}, 0, ErrAttemptsExhausted
		}
		if _, err := New(withKnownBad(spec, state.KnownBad), now); err != nil {
			return Record{}, 0, err
		}
		next := state
		next.ActiveRolloutID = spec.RolloutID
		next.Attempts = make(map[string]int, len(state.Attempts)+1)
		for digest, count := range state.Attempts {
			next.Attempts[digest] = count
		}
		next.Attempts[spec.ToDigest]++
		boundAttempts(next.Attempts, next.KnownBad, spec.ToDigest)
		if err := s.writeCell(ctx, spec.AuthorityEpoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Record{}, 0, err
		}
		return s.createRecord(ctx, spec, next, now)
	}
	return Record{}, 0, ErrConflict
}

store_commit.text:
func sameRollout(existing Record, spec Spec) error {
	if existing.FromDigest != spec.FromDigest || existing.ToDigest != spec.ToDigest || existing.Kind != spec.Kind {
		return fmt.Errorf("%w: rollout ID is bound to a different rollout", ErrConflict)
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return err
	}
	if existing.PolicyDigest != policyDigest || !slices.EqualFunc(existing.Waves, waves, slices.Equal) ||
		!spec.StartedAt.IsZero() && !existing.StartedAt.Equal(spec.StartedAt) {
		return fmt.Errorf("%w: rollout ID is bound to a different plan", ErrConflict)
	}
	return nil
}

func withKnownBad(spec Spec, knownBad []string) Spec {
	spec.KnownBad = append(slices.Clone(spec.KnownBad), knownBad...)
	return spec
}

func (s *Store) createRecord(ctx context.Context, spec Spec, state CellState, now time.Time) (Record, uint64, error) {
	if existing, revision, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		return existing, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	record, err := New(withKnownBad(spec, state.KnownBad), now)
	if err != nil {
		return Record{}, 0, err
	}
	encoded, err := protocol.EncodeJSON(record)
	if err != nil {
		return Record{}, 0, err
	}
	if err := s.fencer.Guard(ctx, record.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	revision, err := s.kv.Create(ctx, rolloutKey(record.RolloutID), encoded)
	if errors.Is(err, jetstream.ErrKeyExists) {
		return s.createRecord(ctx, spec, state, now)
	}
	if err != nil {
		return Record{}, 0, err
	}
	recordAdmitted(ctx, record)
	return record, revision, nil
}

// Commit replaces the record stored at revision with next. Identity fields,
// waves and policy are immutable, and the authority epoch may only change
// through Adopt. A terminal record releases the cell slot.
func (s *Store) Commit(ctx context.Context, revision uint64, next Record) (uint64, error) {
	if err := next.Validate(); err != nil {
		return 0, err
	}
	current, storedRevision, err := s.Load(ctx, next.RolloutID)
	if err != nil {
		return 0, err
	}
	if storedRevision != revision {
		return 0, ErrConflict
	}
	if current.AuthorityEpoch != next.AuthorityEpoch {
		return 0, ErrFenced
	}
	if current.Kind != next.Kind || current.Cell != next.Cell || current.FromDigest != next.FromDigest || current.ToDigest != next.ToDigest ||
		current.PolicyDigest != next.PolicyDigest || !slices.EqualFunc(current.Waves, next.Waves, slices.Equal) ||
		!current.StartedAt.Equal(next.StartedAt) {
		return 0, fmt.Errorf("%w: immutable rollout fields changed", ErrInvalid)
	}
	if current.Phase.Terminal() {
		return 0, ErrTerminal
	}
	encoded, err := protocol.EncodeJSON(next)
	if err != nil {
		return 0, err
	}
	if err := s.fencer.Guard(ctx, next.AuthorityEpoch); err != nil {
		return 0, err
	}
	newRevision, err := s.kv.Update(ctx, rolloutKey(next.RolloutID), encoded, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return 0, ErrConflict
	}
	if err != nil {
		return 0, err
	}
	recordTransition(ctx, current, next)
	if err := s.syncCell(ctx, next); err != nil {
		return newRevision, fmt.Errorf("record committed; cell slot update pending: %w", err)
	}
	return newRevision, nil
}

// Adopt rebinds an active rollout to a newer authority epoch after a leader
// change. An older epoch can never take a record back.
func (s *Store) Adopt(ctx context.Context, rolloutID string, epoch uint64) (Record, uint64, error) {
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return Record{}, 0, err
	}
	record, revision, err := s.Load(ctx, rolloutID)
	if err != nil {
		return Record{}, 0, err
	}
	switch {
	case epoch < record.AuthorityEpoch:
		return Record{}, 0, ErrFenced
	case epoch == record.AuthorityEpoch || record.Phase.Terminal():
		return record, revision, nil
	}
	record.AuthorityEpoch = epoch
	encoded, err := protocol.EncodeJSON(record)
	if err != nil {
		return Record{}, 0, err
	}
	newRevision, err := s.kv.Update(ctx, rolloutKey(rolloutID), encoded, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return Record{}, 0, ErrConflict
	}
	if err != nil {
		return Record{}, 0, err
	}
	return record, newRevision, nil
}

// syncCell merges the record's known-bad digests into the cell and releases
// the slot once the record is terminal.
func (s *Store) syncCell(ctx context.Context, record Record) error {
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return err
		}
		next := state
		next.KnownBad = slices.Clone(state.KnownBad)
		for _, digest := range record.KnownBad {
			if !slices.Contains(next.KnownBad, digest) {
				// Durable first: the cell list below is only a bounded
				// cache of the per-digest records.
				if err := s.recordKnownBad(ctx, record.AuthorityEpoch, digest); err != nil {
					return err
				}
				next.KnownBad = append(next.KnownBad, digest)
			}
		}
		// The list keeps insertion order; the oldest entries age out first.
		// Every entry that ages out keeps its durable record, including
		// entries listed before durable records existed.
		if len(next.KnownBad) > MaxKnownBad {
			for _, digest := range next.KnownBad[:len(next.KnownBad)-MaxKnownBad] {
				if err := s.recordKnownBad(ctx, record.AuthorityEpoch, digest); err != nil {
					return err
				}
			}
			next.KnownBad = next.KnownBad[len(next.KnownBad)-MaxKnownBad:]
		}
		next.Attempts = maps.Clone(state.Attempts)
		if record.Phase.Terminal() && state.ActiveRolloutID == record.RolloutID {
			next.ActiveRolloutID = ""
			// The attempt budget limits retries of a rejected digest. A
			// completed rollout proved its digest; an untouched abort never
			// tried it. Refund once as the slot is released so either can retry.
			if (record.Phase == PhaseComplete || record.abortedBeforeUpdate()) && state.Attempts[record.ToDigest] > 0 {
				if next.Attempts[record.ToDigest]--; next.Attempts[record.ToDigest] == 0 {
					delete(next.Attempts, record.ToDigest)
				}
			}
		}
		boundAttempts(next.Attempts, next.KnownBad, "")
		if slices.Equal(next.KnownBad, state.KnownBad) && next.ActiveRolloutID == state.ActiveRolloutID &&
			maps.Equal(next.Attempts, state.Attempts) {
			return nil
		}
		if err := s.writeCell(ctx, record.AuthorityEpoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else {
			return err
		}
	}
	return ErrConflict
}

func (s *Store) writeCell(ctx context.Context, epoch uint64, state CellState, revision uint64) error {
	if err := state.validate(s.cell); err != nil {
		return err
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if revision == 0 {
		_, err = s.kv.Create(ctx, cellKey, encoded)
	} else {
		_, err = s.kv.Update(ctx, cellKey, encoded, revision)
	}
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return ErrConflict
	}
	return err
}

store_active.text:
func (s *Store) IsKnownBad(ctx context.Context, digest string) (bool, error) {
	if !digestRE.MatchString(digest) {
		return false, fmt.Errorf("%w: known-bad digest", ErrInvalid)
	}
	state, _, err := s.Cell(ctx)
	if err != nil {
		return false, err
	}
	return s.knownBad(ctx, state, digest)
}

// Active returns the record that holds the cell's rollout slot and its KV
// revision. ok is false when the slot is free or names a claim whose record
// was never created; Begin repairs such a slot.
func (s *Store) Active(ctx context.Context) (record Record, revision uint64, ok bool, err error) {
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return Record{}, 0, false, err
	}
	record, revision, err = s.Load(ctx, state.ActiveRolloutID)
	if errors.Is(err, ErrAbandonedRollout) {
		return Record{}, 0, false, nil
	}
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, false, nil
	}
	if err != nil {
		return Record{}, 0, false, err
	}
	return record, revision, true, nil
}

// RecoverReservation abandons a record-free slot before program planning, including a marker-before-clear crash.
func (s *Store) RecoverReservation(ctx context.Context, epoch uint64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return err
	}
	if _, _, err := s.Load(ctx, state.ActiveRolloutID); !errors.Is(err, jetstream.ErrKeyNotFound) && !errors.Is(err, ErrAbandonedRollout) {
		return err
	}
	if err := s.abandon(ctx, epoch, state.ActiveRolloutID); err != nil {
		return err
	}
	return s.releaseSlot(ctx, epoch, state.ActiveRolloutID)
}

// Settle releases the cell slot still held by a terminal record whose
// release was interrupted after its commit, fenced by the caller's epoch.
// It is a no-op for an active record.
func (s *Store) Settle(ctx context.Context, record Record, epoch uint64) error {
	if !record.Phase.Terminal() {
		return nil
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	return s.syncCell(ctx, withEpoch(record, epoch))
}

// Matches reports whether record is the rollout spec describes: the same
// digests, kind, waves and policy. A program uses it before it treats an
// earlier record as its completed prerequisite.
func (record Record) Matches(spec Spec) error {
	if record.RolloutID != spec.RolloutID || record.Cell != spec.Cell {
		return fmt.Errorf("%w: rollout ID is bound to a different rollout", ErrConflict)
	}
	return sameRollout(record, spec)
}

release_read.text:
func generationKey(cell string, generation uint64) string {
	return entityid.Derive("release", cell, strconv.FormatUint(generation, 10))
}

// ReleaseRolloutID is the rollout ID prefix of a desired release generation.
func ReleaseRolloutID(generation uint64) string {
	return entityid.Derive("release-rollout", strconv.FormatUint(generation, 10))
}

// releaseStage resolves derived stage IDs before reading their immutable generation.
func (s *Store) releaseStage(ctx context.Context, id string) (Release, Kind, bool, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, "", false, err
	}
	// Derivation keeps network reads independent of permanent operational history.
	// shortcut: historical IDs cost local hashing; index them if generation counts make that costly.
	for generation := desired.Generation(); generation > 0; generation-- {
		if err := ctx.Err(); err != nil {
			return Release{}, "", false, err
		}
		rolloutID := ReleaseRolloutID(generation)
		for _, stage := range []struct {
			domain string
			kind   Kind
		}{{ControllerReleaseDomain, KindController}, {HostReleaseDomain, KindHost}} {
			if id != entityid.Derive(stage.domain, rolloutID) {
				continue
			}
			release, err := s.generation(ctx, desired, generation)
			if errors.Is(err, ErrNoRelease) {
				return Release{}, "", false, nil
			}
			if err != nil {
				return Release{}, "", false, err
			}
			if release.ID != generationKey(s.cell, generation) {
				return Release{}, "", false, fmt.Errorf("%w: release stage generation ID", ErrInvalid)
			}
			return release, stage.kind, true, nil
		}
	}
	return Release{}, "", false, ctx.Err()
}

// Release is one generation of the cell's desired orchestrator binary.
// Receipt and Delegation are the release receipt the steps carry, so a node
// can restage the binary; nodes verify them against their own roots.
// SourceRevision and RunNumber are what the verified receipt names (the run
// only for an update receipt signed after CI qualified it), so a release
// channel can refuse a run older than the cell's newest. RollbackOf names
// the earlier generation a rollback repeats.
type Release struct {
	ReleaseSequence         uint64    `json:"release_sequence,omitzero"`
	SequenceMigration       []byte    `json:"sequence_migration,omitempty"`
	SequenceMigrationSHA256 string    `json:"sequence_migration_sha256,omitempty"`
	ID                      string    `json:"id"`
	Generation              uint64    `json:"generation"`
	Digest                  string    `json:"digest"`
	SourceRevision          string    `json:"source_revision,omitempty"`
	RunNumber               int64     `json:"run_number,omitzero"`
	Receipt                 []byte    `json:"receipt,omitempty"`
	Delegation              []byte    `json:"delegation,omitempty"`
	RollbackOf              uint64    `json:"rollback_of,omitzero"`
	Actor                   string    `json:"actor"`
	CreatedAt               time.Time `json:"created_at"`
}

func (r Release) validate() error {
	if r.ReleaseSequence == 0 && (len(r.SequenceMigration) > 0 || r.SequenceMigrationSHA256 != "") || r.ReleaseSequence > 0 && (len(r.SequenceMigration) == 0 || !digestRE.MatchString(r.SequenceMigrationSHA256) || len(r.Receipt) == 0 || len(r.Delegation) == 0) || len(r.SequenceMigration) > maxReleaseWire {
		return fmt.Errorf("%w: release sequence metadata", ErrInvalid)
	}
	if !entityid.Valid(r.ID) || r.Generation == 0 || !digestRE.MatchString(r.Digest) || r.RunNumber < 0 ||
		r.SourceRevision != "" && !release.ValidSourceRevision(r.SourceRevision) ||
		len(r.Receipt) > maxReleaseWire || len(r.Delegation) > maxReleaseWire ||
		len(r.Delegation) > 0 && len(r.Receipt) == 0 || r.RollbackOf >= r.Generation ||
		(!tokenRE.MatchString(r.Actor) && !entityid.Valid(r.Actor)) || r.CreatedAt.IsZero() {
		return fmt.Errorf("%w: release generation", ErrInvalid)
	}
	return nil
}

// Desired is the cell's newest release generation. Paused stops the executor
// from starting another rollout; a rollout already running still finishes.
type Desired struct {
	OrderingFloor       Release `json:"ordering_floor,omitzero"`
	LegacyFloor         Release `json:"legacy_floor,omitzero"`
	LegacyIssuanceFloor Release `json:"legacy_issuance_floor,omitzero"`
	SchemaVersion       int     `json:"schema_version"`
	Cell                string  `json:"cell"`
	Release             Release `json:"release,omitzero"`
	Paused              bool    `json:"paused,omitzero"`
}

// Generation is the newest generation, zero before the first release.
func (d Desired) Generation() uint64 { return d.Release.Generation }

func (d Desired) validate(cell string) error {
	if (d.SchemaVersion != SchemaVersion && d.SchemaVersion != DesiredSchemaVersion) || d.Cell != cell {
		return fmt.Errorf("%w: desired release", ErrInvalid)
	}
	if d.SchemaVersion == SchemaVersion && (d.OrderingFloor.Generation != 0 || d.LegacyFloor.Generation != 0 || d.LegacyIssuanceFloor.Generation != 0 || d.Release.ReleaseSequence != 0) {
		return fmt.Errorf("%w: legacy desired schema carries sequence state", ErrInvalid)
	}
	if d.OrderingFloor.Generation > 0 {
		if err := d.OrderingFloor.validate(); err != nil {
			return err
		}
		if d.OrderingFloor.ReleaseSequence == 0 {
			return fmt.Errorf("%w: ordering floor", ErrInvalid)
		}
	}
	for _, floor := range []Release{d.LegacyFloor, d.LegacyIssuanceFloor} {
		if floor.Generation > 0 {
			if err := floor.validate(); err != nil {
				return err
			}
			if floor.ReleaseSequence != 0 {
				return fmt.Errorf("%w: legacy ordering floor", ErrInvalid)
			}
		}
	}
	if d.Release.Generation != 0 {
		if d.Release.ReleaseSequence > d.OrderingFloor.ReleaseSequence {
			return fmt.Errorf("%w: desired exceeds retained ordering floor", ErrInvalid)
		}
		return d.Release.validate()
	}
	return nil
}

// Desired returns the record and its revision (zero when absent).
func (s *Store) Desired(ctx context.Context) (Desired, uint64, error) {
	entry, err := s.kv.Get(ctx, desiredKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Desired{SchemaVersion: DesiredSchemaVersion, Cell: s.cell}, 0, nil
	}
	if err != nil {
		return Desired{}, 0, err
	}
	var desired Desired
	if err := protocol.DecodeTolerant(entry.Value(), &desired, maxRecordBytes); err != nil {
		return Desired{}, 0, err
	}
	if err := desired.validate(s.cell); err != nil {
		return Desired{}, 0, err
	}
	return desired, entry.Revision(), nil
}

// ReleaseGeneration returns one retained generation.
func (s *Store) ReleaseGeneration(ctx context.Context, generation uint64) (Release, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, err
	}
	return s.generation(ctx, desired, generation)
}

// generation reads a retained copy. The copy has no schema version of its
// own: the desired record's, which every caller has validated, covers it. A
// breaking Release change raises DesiredSchemaVersion, so an older controller
// refuses the desired record and never reads a newer generation it would
// misread; a newer binary's added members are skipped, as in the desired
// record itself.
func (s *Store) generation(ctx context.Context, desired Desired, generation uint64) (Release, error) {
	if generation != 0 && generation == desired.Generation() {
		return desired.Release, nil
	}
	if generation == 0 || generation > desired.Generation() {
		return Release{}, fmt.Errorf("%w: %d", ErrNoRelease, generation)
	}
	entry, err := s.kv.Get(ctx, generationKey(s.cell, generation))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Release{}, fmt.Errorf("%w: %d is no longer retained", ErrNoRelease, generation)
	}
	if err != nil {
		return Release{}, err
	}
	var release Release
	if err := protocol.DecodeTolerant(entry.Value(), &release, maxRecordBytes); err != nil {
		return Release{}, err
	}
	if err := release.validate(); err != nil || release.Generation != generation || release.ID != generationKey(s.cell, generation) {
		return Release{}, fmt.Errorf("%w: stored generation %d", ErrInvalid, generation)
	}
	return release, nil
}

// PublishRelease makes release the next generation, fenced by epoch, and
// returns it. A release that repeats the newest generation's binary changes
// nothing and returns ErrReleaseUnchanged, unless a newer CI issuance retries
// an entirely untouched aborted program. A digest known bad in this cell is refused.
func (s *Store) PublishRelease(ctx context.Context, epoch uint64, release Release) (Release, error) {
	if release.ReleaseSequence > 0 || len(release.SequenceMigration) > 0 || release.SequenceMigrationSHA256 != "" || release.RollbackOf != 0 {
		return Release{}, fmt.Errorf("%w: sequenced releases require signature admission; rollbacks require retained generation", ErrInvalid)
	}
	if err := rejectSequencedReceipt(release.Receipt); err != nil {
		return Release{}, err
	}
	return s.publishRelease(ctx, epoch, release, false)
}

release_publish.text:
func (s *Store) publishRelease(ctx context.Context, epoch uint64, release Release, rollback bool) (Release, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if bad, err := s.IsKnownBad(ctx, release.Digest); err != nil {
		return Release{}, err
	} else if bad {
		return Release{}, ErrKnownBad
	}
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return Release{}, err
		}
		seeded, err := s.seedReleaseOrdering(ctx, desired)
		if err != nil {
			return Release{}, err
		}
		next := seeded
		normalized := release
		normalized.Generation = desired.Generation() + 1
		normalized.ID = generationKey(s.cell, normalized.Generation)
		normalized.CreatedAt = release.CreatedAt.UTC()
		if err := normalized.validate(); err != nil {
			return Release{}, err
		}
		if !rollback {
			if err := advanceReleaseOrdering(&next, normalized, s.cell); err != nil {
				return Release{}, err
			}
		}
		if desired.Generation() > 0 && desired.Release.Digest == release.Digest {
			retry, err := s.retryUntouchedRelease(ctx, desired.Release, release)
			if err != nil {
				return Release{}, err
			}
			if !retry {
				if desired.SchemaVersion != DesiredSchemaVersion || desired.OrderingFloor.ReleaseSequence != next.OrderingFloor.ReleaseSequence || desired.LegacyFloor.Generation != next.LegacyFloor.Generation || desired.LegacyIssuanceFloor.Generation != next.LegacyIssuanceFloor.Generation {
					if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
						continue
					} else if err != nil {
						return Release{}, err
					}
				}
				return desired.Release, ErrReleaseUnchanged
			}
		}
		next.Release = normalized
		next.SchemaVersion = DesiredSchemaVersion
		if err := next.validate(s.cell); err != nil {
			return Release{}, err
		}
		// The generation being replaced is retained before the record
		// moves; a copy lost to a crash is written again by the next
		// publish, since the record still holds it.
		if desired.Generation() > 0 {
			if err := s.retain(ctx, epoch, desired.Release); err != nil {
				return Release{}, err
			}
		}
		if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Release{}, err
		}
		if newest := next.Generation(); newest > ReleaseHistory {
			// Best effort: a missed purge only keeps one more old copy.
			oldest := newest - ReleaseHistory
			state, _, err := s.Cell(ctx)
			if err == nil && state.ActiveRolloutID != entityid.Derive(ControllerReleaseDomain, ReleaseRolloutID(oldest)) &&
				state.ActiveRolloutID != entityid.Derive(HostReleaseDomain, ReleaseRolloutID(oldest)) && s.fencer.Guard(ctx, epoch) == nil {
				_ = s.kv.Purge(ctx, generationKey(s.cell, oldest))
			}
		}
		return next.Release, nil
	}
	return Release{}, ErrConflict
}

func (s *Store) retryUntouchedRelease(ctx context.Context, previous, next Release) (bool, error) {
	if previous.RollbackOf != 0 || next.RollbackOf != 0 || !newerReleaseOrder(previous, next) || next.ReleaseSequence == 0 && !next.CreatedAt.After(previous.CreatedAt) {
		return false, nil
	}
	aborted := false
	for _, domain := range []string{ControllerReleaseDomain, HostReleaseDomain} {
		record, _, err := s.Load(ctx, entityid.Derive(domain, ReleaseRolloutID(previous.Generation)))
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			continue
		}
		if errors.Is(err, ErrAbandonedRollout) {
			aborted = true
			continue
		}
		if err != nil || !record.abortedBeforeUpdate() {
			return false, err
		}
		kind := KindController
		if domain == HostReleaseDomain {
			kind = KindHost
		}
		if record.ToDigest != previous.Digest || record.Kind != kind || !record.StartedAt.Equal(previous.CreatedAt) {
			return false, fmt.Errorf("%w: aborted release stage binding", ErrInvalid)
		}
		aborted = true
	}
	return aborted, nil
}

func (s *Store) retain(ctx context.Context, epoch uint64, release Release) error {
	encoded, err := protocol.EncodeJSON(release)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if _, err := s.kv.Put(ctx, generationKey(s.cell, release.Generation), encoded); err != nil {
		return fmt.Errorf("retain release generation: %w", err)
	}
	return nil
}

release_desired_write.text:
func (s *Store) writeDesired(ctx context.Context, epoch uint64, desired Desired, revision uint64) error {
	desired.SchemaVersion = DesiredSchemaVersion
	if err := desired.validate(s.cell); err != nil {
		return err
	}
	encoded, err := protocol.EncodeJSON(desired)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if revision == 0 {
		_, err = s.kv.Create(ctx, desiredKey, encoded)
	} else {
		_, err = s.kv.Update(ctx, desiredKey, encoded, revision)
	}
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return ErrConflict
	}
	return err
}

rollout_new.text:
func New(spec Spec, now time.Time) (Record, error) {
	if now.IsZero() || spec.StartedAt.After(now) {
		return Record{}, fmt.Errorf("%w: start time", ErrInvalid)
	}
	if slices.Contains(spec.KnownBad, spec.ToDigest) {
		return Record{}, ErrKnownBad
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return Record{}, err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return Record{}, err
	}
	units := make(map[string]UnitProgress, len(spec.Units))
	for _, unit := range spec.Units {
		units[unit.ID] = UnitProgress{State: UnitPending, Group: unit.Group, Seed: unit.Seed}
	}
	for wave, ids := range waves {
		for _, id := range ids {
			progress := units[id]
			progress.Wave = wave
			units[id] = progress
		}
	}
	knownBad := slices.Clone(spec.KnownBad)
	slices.Sort(knownBad)
	started := spec.StartedAt
	if started.IsZero() {
		started = now
	}
	record := Record{
		SchemaVersion: SchemaVersion, RolloutID: spec.RolloutID, Kind: spec.Kind, Cell: spec.Cell,
		FromDigest: spec.FromDigest, ToDigest: spec.ToDigest, Policy: spec.Policy, PolicyDigest: policyDigest,
		Phase: PhasePending, Waves: waves, Units: units, KnownBad: slices.Compact(knownBad),
		StartedAt: started.UTC(), PhaseStartedAt: now.UTC(), AuthorityEpoch: spec.AuthorityEpoch,
	}
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	return record, nil
}

rollout_apply.text:
func Apply(record Record, event Event) (Record, error) {
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	if event.At.IsZero() || len(event.Reason) > maxReason {
		return Record{}, fmt.Errorf("%w: event time or reason", ErrInvalid)
	}
	if record.Phase.Terminal() {
		return Record{}, ErrTerminal
	}
	next := record.Clone()
	at := event.At.UTC()
	if completionEvent(event.Kind) || event.Kind == EventStart {
		// A completion that arrives after its phase deadline must not erase
		// that deadline: enforce it first, exactly as a tick at the same
		// instant would, and drop the late completion if it fired.
		phase, wave := next.Phase, next.WaveIndex
		next.tick(at)
		if next.Phase != phase || next.WaveIndex != wave {
			if err := next.Validate(); err != nil {
				return Record{}, err
			}
			return next, nil
		}
	}
	var err error
	switch event.Kind {
	case EventStart:
		err = next.start(at)
	case EventPreflightPassed:
		err = next.preflightPassed(at)
	case EventPreflightFailed:
		err = next.requirePhase(PhasePreflight)
		if err == nil {
			next.finish(PhaseAborted, at, reasonOr(event.Reason, "preflight failed"))
		}
	case EventPrepared:
		err = next.prepared(event.Unit, at)
	case EventHealthy:
		err = next.healthy(event.Unit, event.Health, at)
	case EventUnhealthy, EventHeld:
		// A held forward step rolls back like an unhealthy one; rollback
		// itself, not the forward unit, is what freezes for a human.
		err = next.failed(event.Unit, at, reasonOr(event.Reason, string(event.Kind)))
	case EventRollbackServing:
		err = next.rollbackServing(event.Unit, at)
	case EventRollbackHeld:
		err = next.rollbackHeld(event.Unit, at, reasonOr(event.Reason, "rollback held"))
	case EventTick:
		next.tick(at)
	case EventAbort:
		err = next.abort(at, reasonOr(event.Reason, "operator abort"))
	case EventFreeze:
		if next.Phase == PhaseFrozen {
			return Record{}, ErrInvalidTransition
		}
		next.enter(PhaseFrozen, at, time.Time{}, reasonOr(event.Reason, "frozen"))
	case EventResume:
		err = next.resume(at, event.Left)
	default:
		err = fmt.Errorf("%w: event kind", ErrInvalid)
	}
	if err != nil {
		return Record{}, err
	}
	if err := next.Validate(); err != nil {
		return Record{}, err
	}
	return next, nil
}

// completionEvent reports events that complete a phase with a deadline.
func completionEvent(kind EventKind) bool {
	return kind == EventPreflightPassed || kind == EventPrepared || kind == EventHealthy
}

// boundReason keeps a stored reason within maxReason bytes without splitting
// a UTF-8 rune, so a prefixed failure reason can never fail validation and
// discard the rollback it describes.
func boundReason(reason string) string {
	if len(reason) <= maxReason {
		return reason
	}
	const ellipsis = "..."
	cut := maxReason - len(ellipsis)
	for cut > 0 && !utf8.RuneStart(reason[cut]) {
		cut--
	}
	return reason[:cut] + ellipsis
}

func reasonOr(reason, fallback string) string {
	if reason == "" {
		return fallback
	}
	return reason
}

func (record *Record) requirePhase(phases ...Phase) error {
	if !slices.Contains(phases, record.Phase) {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

func (record *Record) enter(phase Phase, at, deadline time.Time, reason string) {
	if (phase == PhasePreflight || phase.preparing() || phase.soaking()) && deadline.After(record.StartedAt.Add(ObservationBudget)) {
		deadline = record.StartedAt.Add(ObservationBudget)
	}
	record.Phase = phase
	record.PhaseStartedAt = at
	record.PhaseDeadline = deadline
	record.Reason = boundReason(reason)
}

func (record *Record) finish(phase Phase, at time.Time, reason string) {
	record.enter(phase, at, time.Time{}, reason)
}

func (record *Record) start(at time.Time) error {
	if err := record.requirePhase(PhasePending); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.enter(PhasePreflight, at, at.Add(seconds(record.Policy.PreflightSeconds)), "")
	return nil
}

func (record *Record) preflightPassed(at time.Time) error {
	if err := record.requirePhase(PhasePreflight); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.beginWave(0, at)
	return nil
}

// beginWave marks the wave's units as preparing. The executor must only
// issue each prepare after the unit's group peers are serving (see Action).
func (record *Record) beginWave(wave int, at time.Time) {
	record.WaveIndex = wave
	phase := PhaseBatch
	if wave == 0 {
		phase = PhaseCanary
	}
	for _, id := range record.Waves[wave] {
		progress := record.Units[id]
		progress.State = UnitPreparing
		progress.HealthyReports, progress.FirstHealthyAt, progress.ProcessID, progress.StartNonce = 0, time.Time{}, 0, ""
		progress.LastHealthyAt = time.Time{}
		record.Units[id] = progress
	}
	record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
}

func (record *Record) currentWaveUnit(unit string) (UnitProgress, error) {
	progress, exists := record.Units[unit]
	if !exists || progress.Wave != record.WaveIndex {
		return UnitProgress{}, fmt.Errorf("%w: unit %q is not in the current wave", ErrInvalidTransition, unit)
	}
	return progress, nil
}

func (record *Record) prepared(unit string, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	switch progress.State {
	case UnitSoaking:
		return nil
	case UnitPreparing:
	default:
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	progress.State = UnitSoaking
	record.Units[unit] = progress
	if record.Phase.preparing() && record.waveState(UnitSoaking) {
		phase := PhaseBatchSoak
		if record.Phase == PhaseCanary {
			phase = PhaseCanarySoak
		}
		record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
	}
	return nil
}

func (record *Record) waveState(state UnitState) bool {
	for _, id := range record.Waves[record.WaveIndex] {
		if record.Units[id].State != state {
			return false
		}
	}
	return true
}

func (record *Record) healthy(unit string, health Health, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	if progress.State != UnitSoaking {
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	if health.ProcessID <= 0 || !nonceRE.MatchString(health.StartNonce) || health.ObservedAt.IsZero() {
		return fmt.Errorf("%w: health report identity", ErrInvalid)
	}
	if health.ObservedAt.Before(record.PhaseStartedAt) || health.ObservedAt.After(at.Add(time.Minute)) {
		// A report older than the current phase cannot prove the new
		// process, in the preparing phase as little as in the soak: a
		// replayed report would start the soak clock in the past.
		return fmt.Errorf("%w: stale or future health report", ErrInvalid)
	}
	if health.Digest != record.ToDigest {
		record.startRollback(at, fmt.Sprintf("unit %s serves an unexpected digest", unit))
		return nil
	}
	if progress.HealthyReports > 0 && (progress.ProcessID != health.ProcessID || progress.StartNonce != health.StartNonce) {
		record.startRollback(at, fmt.Sprintf("unit %s restarted during soak", unit))
		return nil
	}
	observed := health.ObservedAt.UTC()
	if progress.HealthyReports > 0 && !observed.After(progress.LastHealthyAt) {
		// A replayed or reordered report proves nothing new.
		return nil
	}
	if progress.HealthyReports == 0 {
		progress.FirstHealthyAt = observed
		progress.ProcessID, progress.StartNonce = health.ProcessID, health.StartNonce
	}
	progress.LastHealthyAt = observed
	progress.HealthyReports++
	record.Units[unit] = progress
	record.advanceIfSoaked(at)
	return nil
}

func (record *Record) failed(unit string, at time.Time, reason string) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, exists := record.Units[unit]
	if !exists || !progress.State.touched() {
		return fmt.Errorf("%w: unit %q has not moved", ErrInvalidTransition, unit)
	}
	record.startRollback(at, fmt.Sprintf("unit %s: %s", unit, reason))
	return nil
}

func (record *Record) soakDuration() time.Duration {
	if record.Phase == PhaseCanarySoak {
		return seconds(record.Policy.CanarySoakSeconds)
	}
	return seconds(record.Policy.BatchSoakSeconds)
}

// advanceIfSoaked promotes the wave once every unit has produced the
// required consecutive reports from one incarnation over the soak window.
func (record *Record) advanceIfSoaked(at time.Time) {
	if !record.Phase.soaking() {
		return
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		// The observations, not elapsed tick time, must span the window: a
		// unit that stopped reporting early never completes its soak.
		if progress.State != UnitSoaking || progress.HealthyReports < record.Policy.MinHealthyReports ||
			progress.LastHealthyAt.Before(progress.FirstHealthyAt.Add(record.soakDuration())) {
			return
		}
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		progress.State = UnitPromoted
		record.Units[id] = progress
	}
	if record.WaveIndex+1 < len(record.Waves) {
		record.beginWave(record.WaveIndex+1, at)
		return
	}
	record.finish(PhaseComplete, at, "")
}

func (record *Record) tick(at time.Time) {
	if (record.Phase == PhasePending || record.Phase == PhasePreflight || record.Phase.preparing() || record.Phase.soaking()) &&
		!at.Before(record.StartedAt.Add(ObservationBudget)) {
		reason := "release exceeded its fixed 20-minute observation budget"
		if record.Phase == PhasePending || record.Phase == PhasePreflight {
			record.finish(PhaseAborted, at, reason)
		} else {
			record.startRollback(at, reason)
		}
		return
	}
	switch {
	case record.Phase == PhasePreflight && !at.Before(record.PhaseDeadline):
		record.finish(PhaseAborted, at, "preflight deadline exceeded")
	case record.Phase.preparing() && !at.Before(record.PhaseDeadline):
		record.startRollback(at, "prepare deadline exceeded")
	case record.Phase.soaking():
		if !at.Before(record.PhaseDeadline) {
			for _, id := range record.Waves[record.WaveIndex] {
				if record.Units[id].HealthyReports == 0 {
					record.startRollback(at, fmt.Sprintf("unit %s missed its serving-proof deadline", id))
					return
				}
			}
		}
		wave := record.WaveIndex
		record.advanceIfSoaked(at)
		// Every unit that proved itself before the serving-proof deadline
		// has finished its soak window by deadline+soak, and has reported
		// again within minSoakGap after it. A wave still soaking then has a
		// unit that stopped reporting (for example a hung process after one
		// healthy report); it must not hold the cell's rollout slot forever.
		if record.Phase.soaking() && record.WaveIndex == wave &&
			!at.Before(record.PhaseDeadline.Add(record.soakDuration()).Add(minSoakGap)) {
			record.startRollback(at, "soak did not complete before its deadline")
		}
	case record.Phase == PhaseRollingBack && !at.Before(record.PhaseDeadline):
		head := record.rollbackHead()
		if head != "" {
			progress := record.Units[head]
			progress.State = UnitHeld
			record.Units[head] = progress
		}
		record.enter(PhaseFrozen, at, time.Time{}, "rollback deadline exceeded")
	}
}

// startRollback durably marks ToDigest known bad in the same record write
// that first orders any rollback action, then rolls back every touched unit
// newest first.
func (record *Record) startRollback(at time.Time, reason string) {
	if !slices.Contains(record.KnownBad, record.ToDigest) {
		record.KnownBad = append(record.KnownBad, record.ToDigest)
		slices.Sort(record.KnownBad)
		if len(record.KnownBad) > MaxKnownBad {
			// Keep the current target; the cell list retains the dropped entry.
			drop := 0
			if record.KnownBad[0] == record.ToDigest {
				drop = 1
			}
			record.KnownBad = slices.Delete(record.KnownBad, drop, drop+1)
		}
	}
	var touched []string
	for id, progress := range record.Units {
		if progress.State.touched() {
			touched = append(touched, id)
		}
	}
	slices.SortFunc(touched, func(a, b string) int {
		if order := cmp.Compare(record.Units[b].Wave, record.Units[a].Wave); order != 0 {
			return order
		}
		return cmp.Compare(b, a)
	})
	for _, id := range touched {
		progress := record.Units[id]
		progress.State = UnitRollingBack
		record.Units[id] = progress
	}
	record.RollbackOrder = touched
	if len(touched) == 0 {
		record.finish(PhaseRolledBack, at, reason)
		return
	}
	record.enter(PhaseRollingBack, at, at.Add(seconds(record.Policy.RollbackDeadlineSeconds)), reason)
}

// rollbackHead returns the next unit to return to FromDigest. Rollback moves
// one unit at a time so the group peer of each step keeps serving.
func (record *Record) rollbackHead() string {
	for _, id := range record.RollbackOrder {
		if record.Units[id].State == UnitRollingBack {
			return id
		}
	}
	return ""
}

func (record *Record) rollbackServing(unit string, at time.Time) error {
	if err := record.requirePhase(PhaseRollingBack); err != nil {
		return err
	}
	if head := record.rollbackHead(); head != unit {
		if progress, exists := record.Units[unit]; exists && progress.State == UnitRolledBack {
			return nil
		}
		return fmt.Errorf("%w: unit %q is not the rollback head", ErrInvalidTransition, unit)
	}
	progress := record.Units[unit]
	progress.State = UnitRolledBack
	record.Units[unit] = progress
	if record.rollbackHead() == "" {
		record.finish(PhaseRolledBack, at, record.Reason)
		return nil
	}
	record.enter(PhaseRollingBack, at, at.Add(seconds(record.Policy.RollbackDeadlineSeconds)), record.Reason)
	return nil
}

func (record *Record) rollbackHeld(unit string, at time.Time, reason string) error {
	if err := record.requirePhase(PhaseRollingBack); err != nil {
		return err
	}
	if head := record.rollbackHead(); head != unit {
		return fmt.Errorf("%w: unit %q is not the rollback head", ErrInvalidTransition, unit)
	}
	progress := record.Units[unit]
	progress.State = UnitHeld
	record.Units[unit] = progress
	// Never retarget ToDigest: a held rollback stops for a human.
	record.enter(PhaseFrozen, at, time.Time{}, reason)
	return nil
}

rollout_actions.text:
func NextActions(record Record) []Action {
	if record.Validate() != nil {
		return nil
	}
	switch {
	case record.Phase == PhasePreflight:
		return []Action{{Kind: ActionPreflight, Deadline: record.PhaseDeadline}}
	case record.Phase.preparing() || record.Phase.soaking():
		var actions []Action
		for _, id := range record.Waves[record.WaveIndex] {
			progress := record.Units[id]
			switch progress.State {
			case UnitPreparing:
				actions = append(actions, Action{
					Kind: ActionPrepare, Unit: id, Digest: record.ToDigest,
					OperationID: OperationID(record.RolloutID, id, record.Phase, progress.Attempts),
					Peers:       record.peers(id), Deadline: record.PhaseDeadline,
				})
			case UnitSoaking:
				actions = append(actions, Action{Kind: ActionAwaitHealth, Unit: id, Digest: record.ToDigest, Deadline: record.PhaseDeadline})
			}
		}
		return actions
	case record.Phase == PhaseRollingBack:
		head := record.rollbackHead()
		if head == "" {
			return nil
		}
		return []Action{{
			Kind: ActionRollback, Unit: head, Digest: record.FromDigest,
			OperationID: OperationID(record.RolloutID, head, PhaseRollingBack, record.Units[head].Attempts),
			Peers:       record.peers(head), Deadline: record.PhaseDeadline,
		}}
	case record.Phase == PhaseFrozen:
		return []Action{{Kind: ActionPage}}
	}
	return nil
}

// peers lists the other units of id's group. A step may only start while
// they are serving, which keeps the group above quorum.
func (record Record) peers(id string) []string {
	group := record.Units[id].Group
	var peers []string
	for other, progress := range record.Units {
		if other != id && progress.Group == group {
			peers = append(peers, other)
		}
	}
	slices.Sort(peers)
	return peers
}

